window.COURSES=window.COURSES||{};window.COURSES.css={"id":"css","name":"CSS","title":"CSS Forge","updated":"2026-10-23","hours":144,"description":"Da primeira regra a interfaces responsivas e acessíveis, com layout, estados, temas e investigação de problemas de CSS.","prerequisites":["Nenhuma linguagem anterior é obrigatória; a estrutura HTML necessária é apresentada na trilha.","Computador com navegador moderno e editor de texto.","Saber criar uma pasta e salvar um arquivo; os exemplos não exigem Node.js nem instalação de pacotes."],"outcome":"Construir e revisar um painel responsivo de ordens de serviço e estoque, com navegação por teclado, temas e regras de CSS organizadas.","extension":"html","codeLanguage":"html","setup":[{"title":"Arquivo e navegador","text":"Crie css-forge e uma pasta por aula. Salve o exemplo inteiro como index.html, incluindo HTML e style, e abra no navegador. Ao editar, salve e recarregue. Nenhum exemplo carrega fontes ou bibliotecas externas."},{"title":"Inspeção e dimensões","text":"Abra as ferramentas de desenvolvimento do navegador para inspecionar regras e tamanho das caixas. O modo de dispositivos ajuda a experimentar larguras; complete a revisão com zoom, teclado e, quando disponível, um dispositivo real."},{"title":"Resultado observável","text":"Compare a página com a descrição esperada, altere uma declaração por vez e registre o efeito. A plataforma salva rascunhos; o HTML é aberto no seu ambiente. Consulte a compatibilidade das propriedades antes de adotá-las no seu público."}],"references":[{"title":"MDN — fundamentos de CSS","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics","description":"Seletores, cascata, caixas e primeiras regras."},{"title":"W3C — CSS Cascading and Inheritance Level 5","url":"https://www.w3.org/TR/css-cascade-5/","description":"Origens, importância, camadas e resolução de declarações."},{"title":"W3C — Flexbox","url":"https://www.w3.org/TR/css-flexbox-1/","description":"Modelo de layout flexível e dimensionamento."},{"title":"W3C — Grid Layout Level 2","url":"https://www.w3.org/TR/css-grid-2/","description":"Trilhas, posicionamento e subgrid."},{"title":"MDN — container queries","url":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Containment/Container_queries","description":"Componentes que respondem ao espaço do ancestral."},{"title":"MDN — preferências de movimento","url":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/At-rules/%40media/prefers-reduced-motion","description":"Respeito à preferência por movimento reduzido."},{"title":"web.dev — design responsivo","url":"https://web.dev/learn/design/","description":"Conteúdo, tipografia e layouts adaptáveis."},{"title":"W3C — WCAG 2.2","url":"https://www.w3.org/TR/WCAG22/","description":"Referência para contraste, teclado, foco e reflow."}],"levels":[{"id":1,"title":"Estrutura e primeiras regras","tag":"Fundamentos","hours":12,"summary":"Relacione elementos HTML e regras sem perder a estrutura do documento.","skills":["HTML essencial","Seletores","Cascata"],"project":"Página de apresentação de serviços","deliverables":["Página com título, descrição e lista de serviços.","Regras por elemento e classe organizadas num style.","Registro de uma disputa de cascata e sua explicação."],"rubric":["O HTML permanece compreensível sem estilos.","As classes selecionam os elementos pretendidos.","Explica a regra vencedora sem depender de tentativa aleatória."],"challenge":[{"question":"Uma página tem dois cartões .ordem e apenas um deve mostrar pendência. Qual alteração evita duplicar toda a folha?","options":["Adicionar um estado ou variante ao cartão e escrever uma regra restrita a esse estado.","Mudar todos os p da página para parecerem pendentes.","Criar outro body dentro do cartão.","Substituir o texto da ordem por uma imagem de fundo."],"answer":0,"explanation":"O estado pode ser representado no HTML por classe ou atributo e receber uma regra de alcance deliberado."},{"question":"O body define uma cor; um p define outra diretamente. Em um caso normal, o que explica a cor do p?","options":["O seletor do body sempre vence qualquer descendente.","A declaração aplicável ao próprio p é considerada em vez de apenas herdar a cor do ancestral.","A cor do body é duplicada em todo elemento como estilo inline.","Nenhuma propriedade de texto pode ser herdada."],"answer":1,"explanation":"Herança preenche o valor quando pertinente; ela não disputa como um seletor do ancestral contra toda declaração direta do filho."},{"question":"Duas regras normais de .alerta na mesma camada definem o mesmo color e as etapas anteriores empatam. Qual delas vence?","options":["A que usa o maior valor hexadecimal.","A que possui mais espaços na indentação.","A declaração que aparece depois na ordem pertinente.","A que fica num arquivo com nome mais curto."],"answer":2,"explanation":"Com origem, importância, camada e especificidade empatadas, a ordem decide a declaração vencedora."}]},{"id":2,"title":"Caixas e fluxo","tag":"Fundamentos","hours":12,"summary":"Calcule espaço e deixe o conteúdo crescer sem sobreposição.","skills":["Box model","Display","Overflow"],"project":"Cartões de ordens sem cortes","deliverables":["Três cartões com padding, borda e dimensões coerentes.","Comparação entre content-box e border-box.","Caso de texto longo sem ocultar dados."],"rubric":["Confere a dimensão externa de uma caixa.","Não usa altura fixa para esconder variações de texto.","Mantém o conteúdo disponível em uma largura estreita."],"challenge":[{"question":"Uma caixa content-box tem width:180px, padding:12px em cada lado e border:2px em cada lado. Qual é a largura da caixa de borda?","options":["180px.","192px.","204px.","208px."],"answer":3,"explanation":"Somam-se180 de conteúdo,24 de padding e4 de borda; margens não foram incluídas."},{"question":"Uma observação longa sumiu porque seu cartão tem altura fixa e overflow:hidden. Qual diagnóstico preserva melhor a tarefa de leitura?","options":["Revisar o limite de altura e permitir crescimento ou um acesso deliberado ao conteúdo completo.","Apagar o restante do texto do HTML.","Aumentar z-index sem alterar a caixa.","Tornar todo o texto position:fixed."],"answer":0,"explanation":"Recortar a informação não elimina a necessidade de lê-la; o contrato de tamanho deve ser revisto."},{"question":"Uma distância entre blocos não é a soma de duas margens verticais positivas. Qual fenômeno pode explicar isso no fluxo normal?","options":["Toda margem CSS é sempre ignorada.","Colapso de margens em condições aplicáveis.","O navegador soma apenas margens horizontais em qualquer layout.","A existência de classes impede medidas de espaço."],"answer":1,"explanation":"Certas margens verticais de blocos podem colapsar; gaps em Grid e Flex não seguem essa mesma regra."}]},{"id":3,"title":"Tipografia, cores e medidas","tag":"Fundamentos","hours":12,"summary":"Construa hierarquia visual com medidas e cores verificáveis.","skills":["Unidades","Legibilidade","Contraste"],"project":"Resumo de estoque legível","deliverables":["Resumo com título, quantidades e descrições.","Paleta com pares de texto e fundo documentados.","Tipografia que suporta zoom e quebra de linhas."],"rubric":["O texto continua acessível ao ampliar.","Status não depende apenas de cor.","Justifica unidades e tamanho de linha."],"challenge":[{"question":"Você quer uma coluna de leitura em torno de60ch. Qual limite precisa reconhecer?","options":["Ch sempre significa centímetro.","Ch impede qualquer zoom do navegador.","Ch se relaciona à medida de um glifo da fonte e não garante exatamente60 caracteres por linha.","Ch mede exatamente a quantidade de letras em qualquer idioma."],"answer":2,"explanation":"A fonte e os caracteres reais influenciam o comprimento de linha; ch funciona como uma referência aproximada."},{"question":"Os estados de uma OS são reconhecidos apenas por círculos verde e amarelo. Qual melhoria atende também quando as cores não são distinguidas?","options":["Acrescentar um segundo tom sem texto.","Retirar os estados da impressão.","Aplicar blur aos rótulos.","Incluir o nome textual do estado e usar cor como reforço."],"answer":3,"explanation":"A informação deve sobreviver à ausência de percepção de cor e a outras condições de apresentação."},{"question":"Você removeu gradiente e sombra de um resumo de estoque. Qual resultado indica boa separação entre conteúdo e decoração?","options":["Quantidade, identificação e status continuam compreensíveis no HTML.","Todos os dados desaparecem porque estavam apenas no fundo.","A página perde obrigatoriamente a semântica de main.","Um shadow passa a calcular o saldo de estoque."],"answer":0,"explanation":"A decoração pode mudar ou faltar sem remover a informação necessária à tarefa."}]},{"id":4,"title":"Layout com Flexbox","tag":"Intermediário","hours":12,"summary":"Distribua itens num eixo sem fixar tamanhos para todo conteúdo.","skills":["Eixos","Flex sizing","Wrap"],"project":"Barra de ações responsiva","deliverables":["Barra com título e links de ação.","Grupo que quebra linhas conforme o espaço.","Comparação entre grow, shrink e basis."],"rubric":["Mantém a ordem de leitura do HTML.","Links não cortam texto em largura pequena.","Distingue alinhamento do eixo principal e transversal."],"challenge":[{"question":"Uma barra usa row-reverse para parecer correta, mas a ordem de Tab confunde. Qual revisão costuma ser adequada?","options":["Presumir que row-reverse também reescreve toda ordem de foco.","Organizar primeiro uma sequência lógica no HTML e ajustar a apresentação sem contradizê-la.","Remover o foco de todos os links.","Duplicar cada controle em outra posição."],"answer":1,"explanation":"Ordem visual e ordem do documento não são automaticamente equivalentes; a sequência deve ser coerente."},{"question":"Um flex item com um código longo resiste a encolher. Qual conjunto de decisões merece investigação?","options":["A cor hexadecimal do título apenas.","O nome do arquivo HTML apenas.","O mínimo automático do item e a política de quebra ou acesso ao conteúdo.","A duração de uma animação que nem existe."],"answer":2,"explanation":"Min-inline-size:0 pode permitir redução, mas o conteúdo ainda precisa de uma política apropriada."},{"question":"Você alterou align-content numa única linha flex sem espaço transversal livre e não viu mudança. Qual explicação faz sentido?","options":["Align-content muda sempre a cor dos itens.","Qualquer propriedade sem efeito está necessariamente escrita errado.","Apenas JavaScript pode alinhar linhas de flex.","A distribuição das linhas exige condições como múltiplas linhas e espaço transversal disponível."],"answer":3,"explanation":"É necessário distinguir itens de linhas e verificar o espaço em que a propriedade pode atuar."}]},{"id":5,"title":"Layout com Grid","tag":"Intermediário","hours":12,"summary":"Organize linhas e colunas a partir do conteúdo.","skills":["Trilhas","Áreas","Auto-fit"],"project":"Painel de indicadores","deliverables":["Grade de indicadores com trilhas flexíveis.","Layout de página com áreas nomeadas.","Grade que muda de quantidade de colunas sem cartões minúsculos."],"rubric":["Usa minmax sem provocar overflow inesperado.","A sequência sem CSS mantém sentido.","Explica o papel do espaço disponível no número de colunas."],"challenge":[{"question":"Um grid de cartões usa1fr e estoura por causa do conteúdo. Qual revisão é mais informada?","options":["Inspecionar mínimos das trilhas e dos itens, considerando minmax(0,1fr) e tratamento do conteúdo quando apropriado.","Ocultar a página inteira com overflow:hidden sem inspeção.","Assumir que1fr ignora todo mínimo de conteúdo.","Trocar todos os elementos por position:absolute."],"answer":0,"explanation":"Trilhas flexíveis ainda participam de restrições intrínsecas; o conteúdo e a trilha devem ser revisados juntos."},{"question":"Há espaço para várias trilhas automáticas, mas só existe um cartão. Qual diferença entre auto-fit e auto-fill pode aparecer?","options":["Auto-fill apaga o cartão.","Auto-fit colapsa trilhas vazias; auto-fill as mantém.","Auto-fit obriga uma coluna fixa de1px.","Os dois sempre eliminam toda trilha vazia de forma idêntica."],"answer":1,"explanation":"A diferença nas trilhas não ocupadas pode alterar a largura final dos cartões e a distribuição da grade."},{"question":"Uma mesma área nomeada aparece em células que formam um L em grid-template-areas. Qual revisão é necessária?","options":["Aumentar a especificidade do título.","Colocar mais espaços no nome.","Reformular o mapa para que a área nomeada forme um retângulo válido.","Usar a mesma área de modo descontínuo sem nenhuma restrição."],"answer":2,"explanation":"Áreas nomeadas precisam formar regiões retangulares coerentes na definição da grade."}]},{"id":6,"title":"Design responsivo","tag":"Intermediário","hours":12,"summary":"Escolha adaptações segundo conteúdo, viewport e container.","skills":["Media queries","Fluidez","Container queries"],"project":"Componentes em espaços diferentes","deliverables":["Página com meta viewport e base para telas estreitas.","Título fluido com limites de tamanho.","Mesmo cartão dentro de dois containers com espaços diferentes."],"rubric":["Testa pelo menos duas larguras e zoom.","Tem layout base utilizável sem container queries.","A mudança do componente não depende apenas da tela inteira."],"challenge":[{"question":"Dois cartões na mesma janela têm espaços disponíveis diferentes. Qual recurso consulta diretamente o espaço de um ancestral elegível?","options":["Uma media query de viewport é sempre suficiente para saber o tamanho de qualquer cartão.","Font-weight consulta o tamanho do ancestral.","O nome da classe informa automaticamente a largura ao navegador.","Uma size container query com contexto declarado no ancestral."],"answer":3,"explanation":"Container queries permitem que um componente responda a seu contexto de uso, mantendo uma base funcional."},{"question":"Um título usa apenas font-size:6vw e fica inadequado em algumas condições. Qual revisão é mais consistente com a trilha?","options":["Usar referências e limites apropriados e testar ampliação, em vez de depender apenas do viewport.","Definir uma altura fixa e esconder as linhas restantes.","Desabilitar zoom da página.","Remover o título em telas pequenas."],"answer":0,"explanation":"Funções como clamp podem expressar limites, mas a verificação de legibilidade e zoom continua necessária."},{"question":"Um navegador não aplica a melhoria de container queries de um cartão. O que o projeto deve manter?","options":["Uma página vazia até instalar um framework.","Um layout base legível e utilizável sem a melhoria.","Texto de erro dizendo que CSS nunca funciona.","Obrigatoriamente as mesmas colunas mesmo sem suporte."],"answer":1,"explanation":"Melhoria progressiva oferece uma apresentação suficiente antes dos recursos condicionais."}]},{"id":7,"title":"Estados e acessibilidade","tag":"Avançado","hours":12,"summary":"Torne estados e navegação perceptíveis sem depender de mouse.","skills":["Foco","Formulários","Reflow"],"project":"Formulário de consulta de OS","deliverables":["Campos com labels e instruções explícitas.","Foco visível em links e controles.","Revisão de conteúdo oculto, contraste e reflow."],"rubric":["Percorre os controles por Tab em ordem lógica.","Mantém texto e indicação além de cores para estados.","Não oculta informação essencial com CSS."],"challenge":[{"question":"Um campo usa apenas placeholder para dizer seu propósito. Qual revisão fornece uma identificação mais estável?","options":["Um fundo colorido sem texto.","Uma div sem relação com o controle.","Um label associado ao campo, com instrução adicional quando necessária.","Remover o nome do campo quando ele recebe foco."],"answer":2,"explanation":"Placeholder pode desaparecer e não substitui o contrato de nome e associação do label."},{"question":"O navegador marcou um e-mail como válido. O que ainda não foi demonstrado por esse estado?","options":["Que o valor atendeu às restrições HTML aplicáveis.","Que o elemento pode ter uma borda.","Que um type=email foi usado.","Que a conta existe, pertence à pessoa ou passou pelas regras de autorização do serviço."],"answer":3,"explanation":"Validade de formato local não prova identidade, existência de caixa postal ou autorização."},{"question":"Um texto complementar diferencia links repetidos para OS distintas. Qual cuidado aplica-se ao ocultá-lo visualmente?","options":["Preservar seu papel no nome acessível e verificar a experiência, em vez de simplesmente usar display:none.","Ocultar também todos os links focáveis.","Depender apenas da cor do texto invisível.","Assumir que qualquer técnica de ocultação tem efeitos acessíveis idênticos."],"answer":0,"explanation":"A apresentação visual e a árvore de acessibilidade precisam ser consideradas separadamente."}]},{"id":8,"title":"Posicionamento e camadas","tag":"Avançado","hours":12,"summary":"Investigue deslocamentos, rolagem e sobreposição de elementos.","skills":["Containing block","Sticky","Stacking context"],"project":"Lista de ordens com cabeçalho","deliverables":["Badge ancorado dentro de cartão.","Cabeçalho sticky em região de rolagem delimitada.","Demonstração de dois stacking contexts."],"rubric":["Identifica o ancestral que delimita o posicionamento.","Conteúdo e foco não ficam encobertos.","Resolve a origem do empilhamento em vez de aumentar z-index indefinidamente."],"challenge":[{"question":"Um badge absoluto deveria seguir um cartão, mas aparece ancorado a outra região. O que inspecionar primeiro?","options":["O valor do texto da OS apenas.","Qual ancestral estabelece seu containing block e se o cartão tem o contexto pretendido.","A quantidade de letras do nome da classe.","A cor do fundo da página apenas."],"answer":1,"explanation":"Offsets são resolvidos em relação a um containing block apropriado, não a qualquer caixa que parece próxima."},{"question":"Um cabeçalho sticky encobre a ordem alcançada por um link interno. Qual revisão pode preservar o destino visível?","options":["Remover todos os destinos internos.","Aumentar somente o z-index da ordem sem investigar rolagem.","Considerar a altura real do cabeçalho e espaço de navegação ao alvo, por exemplo scroll-margin, testando zoom.","Tornar todo o conteúdo invisível durante a rolagem."],"answer":2,"explanation":"O destino precisa continuar perceptível; a revisão deve observar contexto de rolagem e tamanho efetivo do cabeçalho."},{"question":"Um menu com z-index:5000 continua atrás de um painel irmão ao seu ancestral. Qual causa é plausível?","options":["O número5000 nunca é permitido.","Z-index sempre compara todos os descendentes globalmente.","Todo menu precisa de um seletor de ID.","O menu está limitado por um stacking context ancestral abaixo do contexto do painel."],"answer":3,"explanation":"A hierarquia dos contextos pode impedir que o número de um descendente supere outro contexto."}]},{"id":9,"title":"Temas e movimento","tag":"Avançado","hours":12,"summary":"Crie variações visuais consistentes e movimento opcional.","skills":["Custom properties","Transições","Reduced motion"],"project":"Painel com tema e feedback","deliverables":["Tokens de cor e espaçamento com escopo definido.","Transição ligada a um estado real de interação.","Animação breve com alternativa de movimento reduzido."],"rubric":["O tema conserva legibilidade de todos os estados.","Não anima toda propriedade indiscriminadamente.","A informação permanece disponível com animação desativada."],"challenge":[{"question":"Uma região escura redefine --texto e --superficie. Como o componente pode continuar usando a mesma regra?","options":["Consumindo os tokens herdados por var, com revisão dos pares de cores efetivos.","Usando o nome escuro como uma palavra-chave nativa de cor.","Ignorando a cascata das custom properties.","Substituindo todo conteúdo textual por imagens."],"answer":0,"explanation":"Tokens com escopo permitem variações consistentes, mas não dispensam contraste e estados."},{"question":"Uma pessoa solicita movimento reduzido. Qual comportamento preserva informação neste curso?","options":["Esconder o status junto com a animação.","Retirar ou reduzir o movimento não essencial e manter conteúdo, foco e interação disponíveis.","Impedir o uso do teclado.","Acelerar uma animação infinita para chamar atenção."],"answer":1,"explanation":"A apresentação pode respeitar a preferência sem remover o significado ou o acesso aos controles."},{"question":"Um componente usa transition:all e depois recebe uma nova propriedade de tamanho. Qual risco de manutenção existe?","options":["All impede qualquer evolução de HTML.","Listar propriedades torna todo custo de renderização zero.","A nova mudança pode ser animada sem que isso tenha sido planejado.","Transições nunca atuam sobre mudanças de valor."],"answer":2,"explanation":"Uma lista explícita de propriedades torna a intenção de interpolação mais controlada."}]},{"id":10,"title":"Arquitetura e componentes","tag":"Especialista","hours":12,"summary":"Organize a folha de estilos para permitir evolução previsível.","skills":["Cascade layers","Especificidade","Contratos de componente"],"project":"Biblioteca pequena de componentes","deliverables":["Camadas declaradas em uma ordem explícita.","Cartão e botão com variantes locais.","Estado sem duplicar seletores muito específicos."],"rubric":["Explica prioridades entre camadas e regras normais fora delas.","Variações de um componente não vazam para outro.","Evita usar important como solução padrão para disputas."],"challenge":[{"question":"Um CSS normal sem camada passou a vencer variantes normais organizadas em layers da mesma origem. Qual explicação deve ser considerada?","options":["Qualquer regra sem camada é ignorada.","O nome components sempre vence qualquer outra regra.","Apenas o tamanho do arquivo decide a cascata.","Regras normais sem camada têm precedência sobre regras normais em camadas nessa origem."],"answer":3,"explanation":"Camadas têm sua própria etapa de prioridade; regras normais fora delas não entram como uma camada inicial fraca."},{"question":"Uma equipe coloca important em duas camadas da mesma origem. Qual detalhe evita uma explicação incompleta?","options":["A ordem de prioridade das camadas para declarações importantes se inverte em relação às normais.","Important elimina qualquer consideração de origem.","Camadas posteriores sempre vencem inclusive entre importantes.","Important cria automaticamente um estilo inline."],"answer":0,"explanation":"A inversão preserva prioridades de proteção entre camadas; não é necessário usar important como prática padrão para aprender essa regra."},{"question":"Um wrapper ganha destaque por :has(input:focus-visible), mas o navegador não aplica essa melhoria. Qual contrato deve permanecer?","options":["O campo deixa de existir porque has define seu HTML.","O input ainda tem label, ajuda e um indicador de foco próprio na base.","A melhoria precisa ser indispensável para saber onde está o foco.","O CSS passa a consultar um banco de dados."],"answer":1,"explanation":"O estado relacional é um reforço visual; a interação essencial deve estar disponível sem ele."}]},{"id":11,"title":"CSS avançado e diagnóstico","tag":"Especialista","hours":12,"summary":"Use recursos progressivos e evidências para corrigir problemas.","skills":["Propriedades lógicas","Subgrid","DevTools"],"project":"Revisão de uma tela problemática","deliverables":["Componente revisado em LTR e RTL.","Alinhamento com subgrid protegido por supports e fallback.","Relato de investigação de overflow ou custo visual."],"rubric":["Testa a versão base sem a melhoria avançada.","Localiza a regra e o tamanho que causam o problema.","Diferencia hipótese visual de medição de desempenho."],"challenge":[{"question":"Uma borda indica o começo da leitura e deve acompanhar LTR e RTL. Qual escolha expressa essa intenção?","options":["Fixar border-left e assumir que esquerda é sempre início.","Traduzir automaticamente com text-align.","Usar uma propriedade lógica de início inline e testar as duas direções.","Retirar todos os números do documento."],"answer":2,"explanation":"Propriedades lógicas acompanham o modo de escrita; direção e tradução continuam sendo tarefas distintas."},{"question":"Cartões com grades internas independentes não alinham suas partes entre colunas. O que subgrid pode acrescentar?","options":["Um banco de dados de alinhamento.","A eliminação da necessidade de fallback.","O mesmo número fixo de pixels para todo texto.","Compartilhamento das trilhas do grid pai na dimensão escolhida, com estrutura e spans coerentes."],"answer":3,"explanation":"Subgrid permite relacionar trilhas entre níveis de grade, mas seu contrato precisa corresponder ao conteúdo."},{"question":"Uma equipe afirma que um efeito visual está lento apenas por parecer complexo. Qual passo produz evidência melhor?","options":["Comparar cargas e interações reproduzíveis com ferramentas de performance e condições registradas.","Adicionar will-change a todos os elementos sem medir.","Culpar qualquer seletor longo automaticamente.","Trocar cores até a hipótese parecer correta."],"answer":0,"explanation":"Uma medição controlada ajuda a separar hipótese de causa e evita otimizações sem evidência."}]},{"id":12,"title":"Entrega e projeto final","tag":"Especialista","hours":12,"summary":"Integre layout, estados e documentação em uma entrega revisável.","skills":["Impressão","Resiliência","Painel integrado"],"project":"Painel CSS de OS e estoque","deliverables":["Painel com navegação, lista de OS e resumo de estoque.","Checklist de revisão com teclado, zoom, textos longos e impressão.","README com estrutura de CSS, compatibilidade e limitações."],"rubric":["Funciona em espaços estreitos sem perda de controles.","Links, foco e regiões do documento permanecem identificáveis.","Demonstra layout base e melhorias sem alegar funcionalidades de backend."],"challenge":[{"question":"Uma ordem é maior que uma folha mesmo usando break-inside:avoid. Qual conclusão é correta?","options":["Avoid garante que qualquer conteúdo caiba magicamente numa folha.","A regra é uma preferência de quebra, e conteúdo maior que a página ainda exige revisão e verificação da saída.","Print remove automaticamente texto excedente de modo seguro.","CSS nunca pode alterar apresentação de impressão."],"answer":1,"explanation":"Paginação depende do conteúdo e da área de saída; a prévia e o artefato precisam ser conferidos."},{"question":"O painel ficou bom com títulos curtos numa tela larga. Qual revisão ainda é necessária?","options":["Afirmar que toda acessibilidade já foi certificada.","Remover qualquer conteúdo que cause quebra.","Testar condições como textos longos, área estreita, zoom e navegação por teclado, registrando o que foi executado.","Considerar um único screenshot uma prova de todos os estados."],"answer":2,"explanation":"A tarefa e as condições de uso variam; a evidência precisa cobrir interação e resiliência, além da imagem inicial."},{"question":"No projeto CSS, os números de estoque são texto estático e details abre localmente. Qual afirmação descreve a entrega com honestidade técnica?","options":["A borda de um cartão executa uma transação de banco.","A abertura de details prova autorização de um usuário.","Uma container query implementa a API de estoque.","A interface demonstra apresentação e interação HTML local, sem confirmar OS ou persistir estoque."],"answer":3,"explanation":"CSS e HTML local têm capacidades concretas; regras de domínio, persistência e integrações precisam de implementação própria."}]}],"lessons":[{"id":1,"level":1,"title":"HTML mínimo e a primeira declaração","goal":"Reconhecer estrutura, seletor, propriedade e valor.","theory":[{"title":"Conteúdo antes da aparência","text":"HTML representa a estrutura: h1 é um título, p é um parágrafo e ul agrupa itens. CSS descreve a apresentação desses elementos. O exemplo é um documento completo; salve também head, style e body para praticar sem precisar de outros arquivos."},{"title":"Uma regra de cada vez","text":"O seletor h1 encontra os títulos desse tipo. Entre chaves, color é a propriedade e #174a7e é seu valor. O ponto e vírgula separa declarações. Uma regra não cria um título ausente no HTML: ela estiliza elementos que já existem."},{"title":"Guardar e observar","text":"Abrir o arquivo mostra a última versão salva. Se a alteração não aparecer, confira o arquivo aberto, o salvamento e se a declaração foi escrita dentro de style. Inspecione o h1 para relacionar uma declaração à aparência, em vez de mudar várias coisas sem previsão."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>HTML mínimo e a primeira declaração</title>\n<style>\nbody { font-family: system-ui, sans-serif; padding: 1.5rem; }\nh1 { color: #174a7e; }\np { line-height: 1.6; }\n</style>\n</head>\n<body>\n<main><h1>Serviços da oficina</h1><p>Instalação e revisão de equipamentos.</p><ul><li>Instalação</li><li>Revisão</li></ul></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"Um título azul escuro, um parágrafo e uma lista aparecem com espaço ao redor.","quiz":{"question":"Qual parte de h1 { color: #174a7e; } escolhe os elementos?","options":["O seletor h1.","O valor #174a7e.","A declaração color inteira cria o elemento.","A extensão do arquivo seleciona o título."],"answer":0,"explanation":"O seletor encontra elementos; a declaração define uma apresentação para eles."},"exercises":[{"title":"Primeiro ajuste","prompt":"Troque a cor do título por #5b246b e descreva o que mudou.","hint":"Edite apenas o valor de color.","solution":"h1 { color: #5b246b; } muda o título, mantendo a estrutura HTML.","criteria":["O título usa a nova cor.","A lista e o texto continuam presentes."],"id":1},{"title":"Nova informação","prompt":"Acrescente um parágrafo com o horário de atendimento e verifique quais regras o alcançam.","hint":"Use um novo elemento p dentro de main.","solution":"O parágrafo também recebe line-height:1.6, pois o seletor p alcança ambos.","criteria":["O horário aparece como parágrafo.","Explica por que os dois parágrafos recebem a regra."],"id":2},{"title":"Desligue a aparência","prompt":"Remova temporariamente style e compare o que continua na página.","hint":"Mantenha os elementos do body.","solution":"O conteúdo e a hierarquia continuam, mas as regras de apresentação do autor deixam de valer. O navegador ainda usa seus estilos padrão.","criteria":["Registra o conteúdo preservado.","Distingue ausência do CSS do autor de ausência de qualquer estilo."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics/What_is_CSS","caution":"","local":true,"hours":4,"minutes":45},{"id":2,"level":1,"title":"Seletores, classes e relações","goal":"Selecionar apenas o componente pretendido sem depender de posição frágil.","theory":[{"title":"Classes dão intenção","text":"Uma classe pode ser usada em vários elementos e um elemento pode ter mais de uma classe. .ordem encontra qualquer elemento com essa classe. O nome deve comunicar uma função ou componente, sem precisar repetir sua aparência atual."},{"title":"Descendência e filho direto","text":"O espaço em .ordem p seleciona parágrafos descendentes, inclusive dentro de outros elementos. O sinal > em .ordem > h2 restringe aos filhos diretos. Escolha a relação necessária, porque uma mudança na estrutura pode ampliar ou reduzir o alcance da regra."},{"title":"Atributos e escopo","text":"Seletores de atributo permitem identificar informações já representadas no HTML, como [data-status=\"pendente\"]. Isso descreve um estado de apresentação, não implementa uma regra de negócio. Evite usar um seletor global de p para corrigir apenas o texto de um cartão."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Seletores, classes e relações</title>\n<style>\nbody { font-family: system-ui; padding: 1rem; }\n.ordem { border: 1px solid #71829a; padding: 1rem; margin-block: 1rem; }\n.ordem > h2 { margin-block-start: 0; }\n.ordem[data-status=\"pendente\"] { border-inline-start: .4rem solid #8a5200; }\n.ordem p { color: #24364b; }\n</style>\n</head>\n<body>\n<main><h1>Ordens</h1><article class=\"ordem\" data-status=\"pendente\"><h2>OS-1</h2><p>Confirmação pendente</p></article><article class=\"ordem\"><h2>OS-2</h2><p>Revisão concluída</p></article><p>Resumo geral fora dos cartões.</p></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"Os dois cartões têm borda e espaçamento; apenas OS-1 possui uma borda inicial mais espessa.","quiz":{"question":"O que .ordem > h2 seleciona?","options":["Qualquer h2 em toda a página.","Elementos h2 que são filhos diretos de um elemento com classe ordem.","Apenas o primeiro h2 do documento.","Um h2 que contém um elemento ordem."],"answer":1,"explanation":"O combinador > restringe a relação ao nível de filho direto."},"exercises":[{"title":"Estado distinto","prompt":"Marque OS-2 com data-status=\"pendente\" e preveja o efeito.","hint":"A regra consulta o atributo.","solution":"OS-2 também recebe a borda inicial; não é necessário duplicar a regra.","criteria":["Os dois cartões exibem o estado.","Explica que o atributo corresponde ao seletor."],"id":1},{"title":"Texto local","prompt":"Adicione uma classe resumo ao parágrafo externo e estilize somente ele em negrito.","hint":"Use .resumo, sem alterar todos os p.","solution":"Acrescente class=\"resumo\" e .resumo { font-weight:700; }.","criteria":["Só o resumo externo ganha o estilo.","Não depende de ser o último parágrafo."],"id":2},{"title":"Estrutura intermediária","prompt":"Envolva o h2 de OS-1 num header e explique por que a regra de margem deixou de alcançá-lo.","hint":"O título deixou de ser filho direto do article.","solution":"Use .ordem h2 se o contrato permitir qualquer descendente, ou mantenha o filho direto conforme o componente exige.","criteria":["Relaciona a mudança ao combinador.","Escolhe uma correção e justifica o alcance."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics/Basic_selectors","caution":"","local":true,"hours":4,"minutes":45},{"id":3,"level":1,"title":"Cascata, herança e especificidade","goal":"Explicar qual declaração vence em um caso controlado.","theory":[{"title":"A cascata resolve conflitos","text":"O navegador reúne declarações aplicáveis e considera etapas como origem, importância e camadas antes da especificidade. Nos exemplos desta aula todas as regras são normais, do autor e sem camadas: podemos isolar o papel dos seletores e da ordem."},{"title":"Especificidade não é uma soma livre","text":"Nesse contexto, uma classe é mais específica que um seletor de elemento. Seletores com a mesma especificidade empatam e a declaração posterior vence. A quantidade de regras repetidas não aumenta a força de uma declaração. Evite iniciar uma disputa com IDs e important para resolver todo ajuste."},{"title":"Herança tem limites","text":"A cor definida no body pode ser herdada por texto descendente quando não há outra declaração pertinente. Uma cor declarada diretamente no elemento prevalece sobre a herdada, mesmo que o seletor do ancestral pareça mais específico. Bordas e margens normalmente não são herdadas."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Cascata, herança e especificidade</title>\n<style>\nbody { color: #24364b; font-family: system-ui; padding: 1rem; }\np { color: #16563b; }\n.aviso { color: #754300; }\np { color: #174a7e; }\nstrong { font-weight: 700; }\n</style>\n</head>\n<body>\n<main><h1>Cascata em observação</h1><p>Parágrafo comum: azul.</p><p class=\"aviso\">Aviso: marrom. <strong>Continua herdando a cor do aviso.</strong></p></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"O parágrafo comum fica azul; o aviso permanece marrom apesar da última regra p. O strong herda a cor marrom.","quiz":{"question":"Por que .aviso vence a última regra p neste exemplo?","options":["Qualquer regra escrita antes sempre vence.","A cor marrom tem prioridade própria.","As condições anteriores da cascata empatam e a classe tem maior especificidade.","Um p não aceita duas regras CSS."],"answer":2,"explanation":"A ordem só decide depois das etapas anteriores empatadas, incluindo especificidade."},"exercises":[{"title":"Empate real","prompt":"Acrescente ao fim .aviso { color:#5b246b; } e preveja a cor do aviso.","hint":"As duas regras de classe têm a mesma especificidade.","solution":"A nova regra de classe vence por ordem, deixando o aviso roxo.","criteria":["Confirma a nova cor.","Explica o empate anterior à ordem."],"id":1},{"title":"Herança","prompt":"Retire a cor do aviso e as regras p, mantendo a cor no body. Explique strong e p.","hint":"Sem cor direta eles podem herdar.","solution":"O texto passa a herdar #24364b; font-weight do strong continua distinto.","criteria":["Distingue cor herdada de peso declarado.","Verifica ambos os elementos."],"id":2},{"title":"Inspeção","prompt":"Abra Computed ou Estilos, localize a declaração de cor vencedora e registre uma regra descartada.","hint":"Declarações sobrescritas costumam aparecer riscadas.","solution":"Registre seletor, arquivo e declaração, explicando a condição que decidiu. Não basta copiar o valor final.","criteria":["Identifica uma regra vencedora e uma perdedora.","A justificativa corresponde ao HTML do exemplo."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Cascade/Introduction","caution":"","local":true,"hours":4,"minutes":45},{"id":4,"level":2,"title":"Box model e tamanho externo","goal":"Calcular conteúdo, padding e borda antes de escolher dimensões.","theory":[{"title":"Uma caixa tem partes","text":"O conteúdo ocupa uma área; padding cria espaço interno e border a envolve. Margin participa da separação externa. Uma largura não informa sozinha o espaço completo ocupado por uma caixa se você não conhecer box-sizing e as outras partes."},{"title":"Duas interpretações de width","text":"Em content-box, width define apenas o conteúdo. Com width:200px, padding de20px em cada lado e borda de2px, a caixa de borda mede244px. Em border-box, os mesmos200px já incluem conteúdo, padding e borda; a área de conteúdo fica menor."},{"title":"Calcular e conferir","text":"O painel de box model nas ferramentas do navegador ajuda a comparar previsão e cálculo. A margem permanece fora de border-box. O padrão global border-box torna várias composições mais previsíveis, mas não elimina conteúdo longo ou mínimos intrínsecos."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Box model e tamanho externo</title>\n<style>\nbody { font-family: system-ui; padding: 1rem; }\n.caixa { width: 200px; padding: 20px; border: 2px solid #174a7e; margin-block: 1rem; background: #eaf3fb; }\n.conteudo { box-sizing: content-box; }\n.borda { box-sizing: border-box; }\n</style>\n</head>\n<body>\n<main><h1>Medindo caixas</h1><div class=\"caixa conteudo\">content-box</div><div class=\"caixa borda\">border-box</div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"A primeira caixa tem244px de largura de borda; a segunda tem200px. A diferença é visível mesmo com a mesma width declarada.","quiz":{"question":"Com border-box, width:200px, padding:20px e borda:2px, qual é a largura da caixa de borda?","options":["244px.","160px.","204px.","200px."],"answer":3,"explanation":"Border-box inclui padding e bordas no tamanho declarado; margens continuam externas."},"exercises":[{"title":"Previsão numérica","prompt":"Mude padding para10px e calcule a largura externa das duas caixas.","hint":"Some apenas no caso content-box.","solution":"Content-box mede224px e border-box continua200px; a área de conteúdo deste cresce.","criteria":["Apresenta os dois valores.","Confere no box model."],"id":1},{"title":"Margem externa","prompt":"Adicione margin-inline:12px e explique se width mudou.","hint":"A margem não entra no border-box.","solution":"A caixa de borda mantém seu tamanho; as margens acrescentam separação na composição.","criteria":["Não soma margem dentro de width.","Identifica separação externa na inspeção."],"id":2},{"title":"Padrão local","prompt":"Crie a regra *, *::before, *::after { box-sizing:border-box; } e remova as variantes de box-sizing.","hint":"O seletor universal pode padronizar a interpretação.","solution":"As duas caixas passam a ter200px de caixa de borda.","criteria":["Compara as duas larguras.","Explica por que o conteúdo interno mudou."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Box_model/Introduction","caution":"","local":true,"hours":4,"minutes":45},{"id":5,"level":2,"title":"Display, fluxo normal e margens","goal":"Distinguir elementos em fluxo e escolher espaço entre conteúdos.","theory":[{"title":"Fluxo normal é a base","text":"Elementos de bloco como p começam uma nova linha e, com largura automática, ocupam o espaço disponível do bloco que os contém. Elementos inline como span participam das linhas de texto. O display pode alterar a geração das caixas, preservando a semântica do HTML."},{"title":"Inline não é um bloco pequeno","text":"Width e height não dimensionam uma caixa inline não substituída como dimensionam um bloco. Inline-block permite uma caixa dimensionável que ainda participa de uma linha. Não transforme toda marcação em inline-block sem considerar quebra, alinhamento e conteúdo."},{"title":"Margens podem colapsar","text":"No fluxo de blocos, certas margens verticais adjacentes podem colapsar em vez de serem somadas. Essa regra não é a mesma que gap em Flexbox ou Grid. Ao depurar espaço, inspecione as caixas e o contexto antes de adicionar margens cada vez maiores."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Display, fluxo normal e margens</title>\n<style>\nbody { font-family: system-ui; padding: 1rem; }\np { margin-block: 1.5rem; }\n.selo { display: inline-block; padding: .3rem .6rem; border: 1px solid #174a7e; }\n.bloco { display: block; background: #eaf3fb; }\n</style>\n</head>\n<body>\n<main><h1>Fluxo de uma ordem</h1><p>OS-1 <span class=\"selo\">Pendente</span> aguarda conferência.</p><p class=\"bloco\">A informação seguinte ocupa outra linha.</p><p>Última observação.</p></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"O selo acompanha a linha e pode quebrar com o texto; os parágrafos formam blocos separados.","quiz":{"question":"Qual escolha cria um selo dimensionável que ainda participa da linha?","options":["display:inline-block.","position:fixed em todo texto.","display:none.","Apenas width em um span inline comum."],"answer":0,"explanation":"Inline-block gera uma caixa atômica dimensionável dentro do contexto inline."},"exercises":[{"title":"Tipo de caixa","prompt":"Troque o selo para display:block e registre a diferença na linha.","hint":"O bloco inicia uma caixa separada.","solution":"O selo passa a ocupar uma linha de bloco, interrompendo a composição anterior.","criteria":["Mostra a mudança de fluxo.","Distingue efeito visual de mudança semântica."],"id":1},{"title":"Espaço previsto","prompt":"Inspecione a distância entre dois p com margens verticais de1.5rem e procure colapso.","hint":"Não pressuponha que o espaço será3rem.","solution":"Em um fluxo de blocos simples, margens positivas adjacentes podem colapsar para a maior. Registre o caso efetivo.","criteria":["Compara previsão e medição.","Explica quando não pode simplesmente somar."],"id":2},{"title":"Estado ausente","prompt":"Aplique display:none ao selo e compare com visibility:hidden.","hint":"Uma opção remove a caixa; a outra preserva o espaço.","solution":"Display:none deixa de gerar a caixa; visibility:hidden a esconde preservando seu espaço no layout.","criteria":["Registra o espaço em ambos os casos.","Reconhece que esconder conteúdo também altera sua disponibilidade acessível."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Display/Block_and_inline_layout_in_normal_flow","caution":"","local":true,"hours":4,"minutes":45},{"id":6,"level":2,"title":"Conteúdo longo, mínimos e overflow","goal":"Manter informação disponível quando o conteúdo excede uma previsão.","theory":[{"title":"Conteúdo define pressão","text":"Uma descrição pode ter mais linhas que a amostra inicial; um identificador pode não ter espaços. Altura fixa e largura rígida tornam essas diferenças visíveis como cortes ou transbordamentos. Comece permitindo altura automática e limite apenas o que faz parte de um contrato real."},{"title":"Quebra de palavras e limites","text":"Overflow-wrap:anywhere permite que uma sequência longa seja quebrada quando necessário. Max-inline-size limita a dimensão sem impedir que a caixa seja menor. Overflow:auto cria rolagem quando existe transbordamento; não é uma correção universal para qualquer layout quebrado."},{"title":"Ocultar não resolve a causa","text":"Overflow:hidden pode esconder conteúdo e também cortar indicadores de foco. Use-o quando a área de recorte é intencional e o conteúdo essencial continua disponível. Para um cartão informativo, geralmente é melhor corrigir tamanho, quebra e estrutura."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Conteúdo longo, mínimos e overflow</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; }\n.ordem { max-inline-size: 28rem; padding: 1rem; border: 2px solid #174a7e; }\n.codigo { overflow-wrap: anywhere; font-family: monospace; }\n.descricao { line-height: 1.6; }\n</style>\n</head>\n<body>\n<main><h1>Texto imprevisível</h1><article class=\"ordem\"><h2>OS-100</h2><p class=\"codigo\">IDENTIFICADORSEMESPACOS123456789012345678901234567890</p><p class=\"descricao\">A descrição pode crescer conforme a equipe registra os detalhes do serviço. O cartão acompanha a quantidade de texto.</p></article></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"O identificador pode quebrar e o cartão cresce na vertical; não há uma altura fixa cortando a descrição.","quiz":{"question":"Uma descrição ficou invisível após height:80px e overflow:hidden. Qual primeira revisão preserva a informação?","options":["Aumentar z-index para999999.","Rever a altura fixa e permitir que o conteúdo determine a altura.","Remover a descrição do HTML.","Tornar a fonte cada vez menor até caber."],"answer":1,"explanation":"A causa é um contrato de altura incompatível com a quantidade de conteúdo, não um problema de empilhamento."},"exercises":[{"title":"Texto de estresse","prompt":"Duplique a descrição três vezes e diminua a janela.","hint":"Deixe a altura automática.","solution":"O cartão deve crescer e as linhas quebrar sem esconder partes da descrição.","criteria":["Todo o texto continua disponível.","Não surge corte por altura fixa."],"id":1},{"title":"Comparação de quebra","prompt":"Remova overflow-wrap e compare o identificador em uma janela estreita.","hint":"A sequência não tem pontos naturais de quebra.","solution":"Registre o transbordamento e restaure uma política de quebra apropriada ao identificador.","criteria":["Mostra a diferença na mesma largura.","Explica por que o texto comum se comporta diferente."],"id":2},{"title":"Região rolável","prompt":"Crie uma região separada de log com max-block-size:8rem e overflow:auto, mantendo um título visível.","hint":"Rolagem faz sentido quando a região é deliberadamente limitada.","solution":"Uma área de log pode rolar, mas o cartão de descrição não precisa ser recortado. Teste teclado e acesso ao conteúdo.","criteria":["O log permanece alcançável.","Justifica por que a região tem um limite."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics/Overflow","caution":"","local":true,"hours":4,"minutes":45},{"id":7,"level":3,"title":"Unidades, tipografia e leitura","goal":"Escolher tamanho de texto e comprimento de linha com contexto.","theory":[{"title":"Unidades carregam referência","text":"Rem se relaciona ao tamanho de fonte do elemento raiz. Em em, a referência depende da propriedade; no font-size ela deriva da fonte do pai. Porcentagens também dependem da propriedade e da dimensão de referência. Escolha a unidade por esse significado, não por uma regra de que px é sempre errado."},{"title":"Ritmo de leitura","text":"Uma line-height sem unidade acompanha o tamanho da fonte de cada elemento que a herda. Limitar uma coluna em ch é uma aproximação útil para comprimento de linha, porque ch se relaciona à medida do glifo zero da fonte; não garante um número exato de caracteres."},{"title":"Zoom faz parte da revisão","text":"Uma interface que parece legível numa tela grande pode falhar ao ampliar ou alterar a fonte. Use conteúdo suficiente e confira se as caixas crescem. Não reduza a fonte automaticamente para esconder overflow de um texto essencial."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Unidades, tipografia e leitura</title>\n<style>\nbody { font-family: system-ui, sans-serif; font-size: 1rem; line-height: 1.6; margin: 0; padding: 1.25rem; color: #172b42; }\nmain { max-inline-size: 60ch; margin-inline: auto; }\nh1 { font-size: 2rem; line-height: 1.2; }\n.detalhe { font-size: .95rem; }\n</style>\n</head>\n<body>\n<main><h1>Resumo de atendimento</h1><p>Uma ordem de serviço deve permitir que a equipe encontre o cliente, identifique o serviço e confira as informações sem depender de uma tela específica.</p><p class=\"detalhe\">Dados fictícios para estudar tipografia e quebra de linhas.</p></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"O texto forma uma coluna limitada e centralizada, com altura de linha confortável e título maior. O conteúdo cresce ao ampliar.","quiz":{"question":"O que line-height:1.6 sem unidade expressa?","options":["Uma altura fixa de1.6px.","Exatamente1.6 linhas em qualquer caixa.","Um fator aplicado ao tamanho da fonte do próprio elemento.","Uma margem externa de1.6rem."],"answer":2,"explanation":"O valor numérico funciona como multiplicador e é herdado sem se fixar em um comprimento calculado do pai."},"exercises":[{"title":"Texto ampliado","prompt":"Amplie a página para200% e registre como o parágrafo e o título se reorganizam.","hint":"Observe conteúdo e limites das caixas.","solution":"Eles devem continuar legíveis, quebrando linhas e aumentando a altura; ajuste limites que causarem perda.","criteria":["Todo o texto fica disponível.","Registra a ampliação usada."],"id":1},{"title":"Referência de tamanho","prompt":"Coloque font-size:1.25rem em main e compare um filho com1em e outro com1rem.","hint":"No font-size, em usa a fonte herdada.","solution":"O filho1em acompanha a fonte de main; o1rem usa a fonte raiz, sem presumir que ela sempre seja16px.","criteria":["Relaciona os tamanhos às referências.","Não trata16px como uma garantia universal."],"id":2},{"title":"Linha muito longa","prompt":"Retire max-inline-size, compare numa janela larga e escolha um limite de leitura.","hint":"Teste com um parágrafo real.","solution":"Reponha um limite como60ch ou outro justificado pelo conteúdo e fonte.","criteria":["Compara antes e depois.","Explica por que ch é uma aproximação."],"id":3}],"source":"https://web.dev/learn/design/typography","caution":"","local":true,"hours":4,"minutes":45},{"id":8,"level":3,"title":"Cores, contraste e informação redundante","goal":"Usar cor com texto e verificar contraste em estados reais.","theory":[{"title":"Cor tem contexto","text":"Uma cor só é legível em relação ao fundo em que aparece. Transparência, imagem de fundo e estados de interação alteram a combinação real. Defina pares de texto e fundo e confira o resultado, incluindo os estados de foco e controles desabilitados."},{"title":"Referência de contraste","text":"WCAG estabelece referências como4,5:1 para texto normal e3:1 para texto grande nas condições do critério de contraste mínimo. Não adivinhe a razão pela aparência: use um verificador ou as ferramentas do navegador. Tamanho e peso precisam corresponder à definição aplicada."},{"title":"Cor não carrega tudo","text":"Um status verde ou amarelo pode não ser distinguido por todas as pessoas e pode perder significado ao imprimir. Acrescente o texto do estado e, se útil, outro sinal que não substitua a informação textual. CSS pode reforçar, mas a informação deve existir no HTML."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Cores, contraste e informação redundante</title>\n<style>\nbody { font-family: system-ui; padding: 1rem; color: #172b42; background: #fff; }\n.estado { display: inline-block; padding: .4rem .7rem; border: 2px solid currentColor; font-weight: 700; }\n.pendente { color: #704000; background: #fff2d4; }\n.concluida { color: #155534; background: #e8f6ee; }\n</style>\n</head>\n<body>\n<main><h1>Status das ordens</h1><p>OS-1: <span class=\"estado pendente\">Pendente de conferência</span></p><p>OS-2: <span class=\"estado concluida\">Concluída</span></p></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"Os dois estados têm textos, bordas e combinações diferentes; o significado permanece se você ignorar as cores.","quiz":{"question":"Qual escolha comunica um status sem depender apenas de cor?","options":["Mostrar apenas um círculo colorido sem texto.","Esconder o status de quem usa alto contraste.","Usar uma cor diferente, mas sem legenda ou texto.","Exibir o nome do status no conteúdo e usar cor como reforço."],"answer":3,"explanation":"A informação textual preserva significado quando cores não podem ser distinguidas."},"exercises":[{"title":"Pares medidos","prompt":"Meça texto e fundo de cada estado com uma ferramenta de contraste. Registre os valores e o critério aplicado.","hint":"Avalie a combinação efetiva, não o hexadecimal isolado.","solution":"Anote as razões medidas e confirme se atendem ao tamanho/peso usados; ajuste a paleta se necessário.","criteria":["Apresenta medidas para os dois estados.","Relaciona as medidas ao texto real."],"id":1},{"title":"Sem cores","prompt":"Desative temporariamente as cores dos estados e confira o que ainda permite reconhecê-los.","hint":"Leia o HTML renderizado.","solution":"Os textos Pendente de conferência e Concluída mantêm a informação.","criteria":["Os estados continuam identificáveis.","Explica o papel de reforço visual."],"id":2},{"title":"Novo estado","prompt":"Crie Cancelada com texto e um par de cores verificável, sem reutilizar só uma bolinha.","hint":"Aplique a mesma estrutura de estado.","solution":"Adicione classe própria e conteúdo Cancelada; registre o contraste sobre seu fundo.","criteria":["O novo estado contém informação textual.","Confere o par de cores escolhido."],"id":3}],"source":"https://www.w3.org/TR/WCAG22/#contrast-minimum","caution":"","local":true,"hours":4,"minutes":45},{"id":9,"level":3,"title":"Fundos, bordas e decoração","goal":"Separar informação estrutural de aparência decorativa.","theory":[{"title":"Fundo não é conteúdo","text":"Backgrounds podem criar superfícies e decoração, mas não substituem o texto necessário para compreender uma ordem. O gradiente desta aula é decorativo: seu desaparecimento não remove título, quantidade ou status."},{"title":"Bordas e preenchimento","text":"Border participa do tamanho da caixa; box-shadow desenha um efeito sem reservar espaço no fluxo. Sombras grandes podem atingir outras áreas e não constituem uma separação semântica. Defina padding para afastar conteúdo da borda, sem depender de espaços no texto."},{"title":"Cantos não garantem qualidade","text":"Border-radius altera a forma visual dos cantos. Ele não torna um cartão interativo e não transforma div em botão. Mantenha as escolhas de semântica do HTML independentes da aparência que você está criando."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Fundos, bordas e decoração</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; background: #edf2f8; color: #172b42; }\n.resumo { max-inline-size: 28rem; padding: 1.5rem; border: 1px solid #8a9bb0; border-radius: 1rem; background: linear-gradient(135deg, #fff, #eaf3fb); box-shadow: 0 .3rem .8rem #172b421a; }\n.resumo h2 { margin-block-start: 0; }\n</style>\n</head>\n<body>\n<main><h1>Estoque</h1><section class=\"resumo\"><h2>Equipamento A</h2><p><strong>12 unidades disponíveis</strong></p><p>Conferência registrada hoje.</p></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"Um cartão arredondado com borda, gradiente claro e sombra apresenta as12 unidades como texto real.","quiz":{"question":"Qual afirmação distingue border de box-shadow neste cartão?","options":["A borda participa da caixa; a sombra não reserva espaço no fluxo.","A sombra sempre altera width.","A borda cria automaticamente um botão.","Border-radius substitui o título acessível."],"answer":0,"explanation":"O efeito da sombra é desenhado sem aumentar a dimensão usada no fluxo."},"exercises":[{"title":"Decoração removida","prompt":"Remova background e box-shadow do cartão. Verifique se há alguma informação perdida.","hint":"O estoque está no HTML.","solution":"As12 unidades e a descrição permanecem; apenas a decoração muda.","criteria":["Todo o conteúdo permanece.","Distingue aparência de informação."],"id":1},{"title":"Caixa medida","prompt":"Troque a borda de1px para6px e compare com e sem box-sizing:border-box usando uma largura definida.","hint":"Retome a regra do box model.","solution":"Com border-box a dimensão declarada inclui a borda; com content-box ela se soma ao tamanho de conteúdo.","criteria":["Registra duas medidas.","Explica o espaço de conteúdo disponível."],"id":2},{"title":"Coerência","prompt":"Crie um segundo resumo com quantidade diferente e reutilize a classe, sem duplicar todo CSS.","hint":"O componente pode receber conteúdo distinto.","solution":"Use outra section.resumo com seu h2 e quantidade; o estilo comum é mantido numa regra.","criteria":["Os dois cartões usam a mesma estrutura.","Não cria seletor pelo texto da quantidade."],"id":3}],"source":"https://www.w3.org/TR/css-backgrounds-3/","caution":"","local":true,"hours":4,"minutes":45},{"id":10,"level":4,"title":"Flexbox e seus eixos","goal":"Relacionar alinhamento principal e transversal à direção do flex.","theory":[{"title":"Um eixo por decisão","text":"Display:flex transforma os filhos diretos em flex items. Flex-direction define o eixo principal; em row ele acompanha o eixo inline da escrita. O eixo transversal é perpendicular. As palavras horizontal e vertical podem confundir quando mudam direção ou modo de escrita."},{"title":"Distribuição e alinhamento","text":"Justify-content distribui espaço livre no eixo principal; align-items controla o alinhamento no transversal. Para observar align-items, o container precisa ter espaço transversal disponível. Gap cria espaçamento entre itens, sem exigir margem em cada filho."},{"title":"Ordem visual e leitura","text":"Row-reverse e order podem mudar a apresentação sem reorganizar a sequência do documento. Isso pode produzir uma ordem de foco diferente da ordem visual. Comece com HTML em ordem lógica e use alinhamento para organizar a aparência."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Flexbox e seus eixos</title>\n<style>\nbody { font-family: system-ui; padding: 1rem; }\n.barra { display: flex; gap: 1rem; justify-content: space-between; align-items: center; padding: 1rem; border: 2px solid #174a7e; }\n.barra a { color: #174a7e; padding: .5rem; }\n</style>\n</head>\n<body>\n<main><h1>Barra de ordens</h1><nav class=\"barra\" aria-label=\"Seções da ordem\"><a href=\"#resumo\">Resumo</a><a href=\"#evidencias\">Evidências</a><a href=\"#estoque\">Estoque</a></nav><section id=\"resumo\"><h2>Resumo</h2></section><section id=\"evidencias\"><h2>Evidências</h2></section><section id=\"estoque\"><h2>Estoque</h2></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"Os três links formam uma linha distribuída com espaçamento; cada link aponta para uma seção presente.","quiz":{"question":"Em flex-direction:row, qual propriedade distribui espaço livre no eixo principal?","options":["align-items em qualquer direção.","justify-content.","font-weight.","overflow-wrap."],"answer":1,"explanation":"Justify-content age no eixo principal definido pela direção do flex container."},"exercises":[{"title":"Direção","prompt":"Mude flex-direction para column e explique o novo papel de justify-content.","hint":"O eixo principal muda.","solution":"Justify-content continua no principal, agora na direção de coluna; pode ser necessário espaço de altura para observar distribuição.","criteria":["Identifica os dois eixos.","Não trata justify-content como sempre horizontal."],"id":1},{"title":"Acesso por teclado","prompt":"Percorra os links com Tab e compare a sequência com a ordem do HTML.","hint":"Não use order neste exercício.","solution":"Resumo, Evidências e Estoque aparecem nessa sequência lógica.","criteria":["Registra a ordem de foco.","Os três destinos existem no documento."],"id":2},{"title":"Espaçamento","prompt":"Troque gap para.5rem e retire justify-content:space-between. Compare o resultado.","hint":"Sem distribuição extra, sobra de espaço pode ficar ao final.","solution":"Os links ficam próximos no início com intervalos de.5rem entre si.","criteria":["Distingue gap de espaço distribuído.","Explica o espaço livre restante."],"id":3}],"source":"https://www.w3.org/TR/css-flexbox-1/","caution":"","local":true,"hours":4,"minutes":45},{"id":11,"level":4,"title":"Flex grow, shrink, basis e mínimos","goal":"Prever dimensionamento flexível sem supor larguras iguais.","theory":[{"title":"Base antes do crescimento","text":"Flex-basis fornece uma base para o algoritmo de dimensionamento. Flex-grow distribui espaço positivo segundo fatores; ele não significa uma porcentagem da largura total. Padding, bordas e mínimos também entram no resultado, então dois números de grow não garantem proporções finais exatas em qualquer situação."},{"title":"Encolhimento é condicionado","text":"Flex-shrink participa da distribuição de espaço negativo e considera a base flexível. Mesmo um item com shrink pode resistir a diminuir por seu mínimo automático e pelo conteúdo. Min-inline-size:0 permite que um item reduza abaixo desse mínimo quando a política de conteúdo permitir."},{"title":"Texto precisa de tratamento","text":"Uma caixa menor não faz um código sem espaços quebrar sozinho. Combine a decisão de tamanho com overflow-wrap ou outra política pertinente. Não esconda a informação essencial apenas para produzir duas colunas visualmente limpas."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Flex grow, shrink, basis e mínimos</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; }\n.linha { display: flex; gap: 1rem; max-inline-size: 44rem; }\n.item { flex: 1 1 12rem; min-inline-size: 0; padding: 1rem; border: 1px solid #174a7e; overflow-wrap: anywhere; }\n.destaque { flex-grow: 2; }\n</style>\n</head>\n<body>\n<main><h1>Distribuição flexível</h1><div class=\"linha\"><section class=\"item\"><h2>OS-1</h2><p>Revisão</p></section><section class=\"item destaque\"><h2>OS-2</h2><p>IDENTIFICADORSEMESPACOS12345678901234567890123456789</p></section></div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"Os cartões partem da mesma base; havendo espaço extra o segundo recebe uma parcela maior desse espaço. O código pode quebrar sem ser ocultado.","quiz":{"question":"Por que usar min-inline-size:0 no flex item com identificador longo?","options":["Para garantir largura zero em toda tela.","Para impedir qualquer flex-shrink.","Para permitir redução além do mínimo automático, acompanhada de uma política de quebra.","Para alterar o texto do identificador."],"answer":2,"explanation":"O mínimo automático pode limitar o encolhimento; zerá-lo abre espaço para a política de quebra adotada."},"exercises":[{"title":"Bases","prompt":"Mude a base de12rem para8rem e compare numa largura fixa.","hint":"O espaço distribuído é o que resta depois das bases e demais custos.","solution":"A distribuição muda; registre as medidas em vez de assumir que grow2 resulta sempre no dobro da largura total.","criteria":["Mede os dois itens.","Distingue base de parcela de espaço extra."],"id":1},{"title":"Mínimo","prompt":"Retire min-inline-size:0 e overflow-wrap separadamente, observando o identificador.","hint":"Altere uma regra por vez.","solution":"Compare a pressão do mínimo e a ausência de quebra; restaure as escolhas que preservam conteúdo no layout.","criteria":["Documenta as duas alterações.","Não conclui que uma única propriedade resolve qualquer texto."],"id":2},{"title":"Prioridade","prompt":"Adicione um pequeno terceiro item com flex:0 0 5rem e explique o contrato.","hint":"Grow0 e shrink0 não participam dessas distribuições.","solution":"O terceiro item mantém uma base fixa de5rem, podendo aumentar a pressão sobre os outros; teste uma largura estreita.","criteria":["Identifica a base fixa.","Registra o comportamento quando falta espaço."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Flexible_box_layout/Controlling_flex_item_ratios","caution":"","local":true,"hours":4,"minutes":45},{"id":12,"level":4,"title":"Wrap, alinhamento de linhas e barras de ações","goal":"Deixar grupos quebrarem sem alterar sua ordem lógica.","theory":[{"title":"Itens podem formar linhas","text":"Flex-wrap:wrap permite novas linhas quando os itens não cabem segundo suas bases e restrições. Cada linha flexível é dimensionada de forma independente. Isso é diferente de alinhar colunas de várias linhas num Grid."},{"title":"Tamanho confortável de ação","text":"Um link ou botão precisa de texto legível, espaço para interação e foco identificável. Quebrar a barra em novas linhas pode preservar essas condições melhor do que reduzir todos os controles. O conteúdo do rótulo é parte do teste, especialmente em tradução."},{"title":"Linhas não são itens","text":"Align-items alinha itens dentro de cada linha; align-content distribui as próprias linhas quando existe espaço transversal livre e mais de uma linha. Sem essa condição, modificar align-content pode não causar um efeito visível."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Wrap, alinhamento de linhas e barras de ações</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; }\n.acoes { display: flex; flex-wrap: wrap; gap: .75rem; align-items: center; max-inline-size: 35rem; }\n.acoes a { display: inline-block; padding: .75rem 1rem; color: #fff; background: #174a7e; border-radius: .4rem; text-decoration: none; }\na:focus-visible { outline: 3px solid #8a5200; outline-offset: 3px; }\n</style>\n</head>\n<body>\n<main><h1>Ações da OS-1</h1><nav class=\"acoes\" aria-label=\"Navegação da OS\"><a href=\"#dados\">Conferir dados</a><a href=\"#fotos\">Ver evidências do atendimento</a><a href=\"#historico\">Consultar histórico</a></nav><section id=\"dados\"><h2>Dados</h2></section><section id=\"fotos\"><h2>Evidências</h2></section><section id=\"historico\"><h2>Histórico</h2></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve todo o exemplo como index.html, abra no navegador e recarregue depois de salvar alterações. Use as ferramentas de desenvolvimento para conferir as regras.","expected":"Os links ocupam uma ou mais linhas conforme o espaço. Os rótulos ficam inteiros, e o foco por teclado tem contorno.","quiz":{"question":"Uma barra precisa quebrar controles mantendo seus rótulos. Qual é uma escolha inicial apropriada?","options":["White-space:nowrap e overflow:hidden em tudo.","Diminuir a fonte indefinidamente.","Reordenar o HTML a cada largura.","Flex-wrap:wrap com gap e dimensões que permitam o conteúdo."],"answer":3,"explanation":"Permitir novas linhas costuma preservar legibilidade sem mudar a sequência lógica."},"exercises":[{"title":"Janela estreita","prompt":"Reduza a largura até a barra formar mais de uma linha e anote em que ponto o conteúdo pede mudança.","hint":"O rótulo mais longo influencia o espaço necessário.","solution":"Registre a largura aproximada e confirme que todos os links continuam utilizáveis.","criteria":["Nenhum rótulo é cortado.","A ordem de foco continua lógica."],"id":1},{"title":"Texto variável","prompt":"Troque Conferir dados por Conferir dados completos da instalação.","hint":"Não crie uma largura fixa só para o rótulo inicial.","solution":"A barra pode ocupar mais linhas, preservando texto e espaçamento.","criteria":["A nova frase aparece completa.","O restante da página continua alcançável."],"id":2},{"title":"Linhas independentes","prompt":"Compare o alinhamento da segunda linha com a primeira e explique por que Flexbox não cria automaticamente colunas comuns.","hint":"Cada linha resolve seu próprio espaço.","solution":"Se as colunas precisarem se alinhar entre linhas, considere Grid; wrap não sincroniza suas trilhas.","criteria":["Explica a independência das linhas.","Apresenta um caso em que Grid seria mais adequado."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Flexible_box_layout/Mastering_wrapping_of_flex_items","caution":"","local":true,"hours":4,"minutes":45},{"id":13,"level":5,"title":"Grid, trilhas e unidades fr","goal":"Construir uma grade e explicar o papel dos mínimos nas colunas.","theory":[{"title":"Linhas e colunas","text":"Display:grid estabelece um contexto de grade para seus filhos diretos. Grid-template-columns define as trilhas de coluna, enquanto as linhas podem ser criadas conforme a quantidade de itens. Gap reserva intervalos entre trilhas sem exigir margens em cada cartão."},{"title":"Frações do espaço disponível","text":"A unidade fr representa uma fração do espaço disponível para trilhas flexíveis, depois de considerar outras restrições. Uma coluna1fr não é sempre metade da janela: o container, os gaps, as demais trilhas e os mínimos importam para o cálculo."},{"title":"Mínimo controlado","text":"Uma trilha definida apenas por1fr tem um mínimo automático que pode reagir ao conteúdo. Minmax(0,1fr) permite um mínimo zero, mas isso não resolve sozinho um texto sem quebra dentro do item. Coordene a decisão de trilha com as regras do conteúdo e preserve a informação."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Grid, trilhas e unidades fr</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\n.indicadores { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; max-inline-size: 42rem; }\n.indicador { padding: 1rem; border: 1px solid #71829a; overflow-wrap: anywhere; }\n.indicador h2 { margin-block-start: 0; }\n</style>\n</head>\n<body>\n<main><h1>Indicadores</h1><div class=\"indicadores\"><section class=\"indicador\"><h2>Abertas</h2><p>8 ordens</p></section><section class=\"indicador\"><h2>Concluídas</h2><p>12 ordens</p></section><section class=\"indicador\"><h2>Estoque</h2><p>25 equipamentos</p></section><section class=\"indicador\"><h2>Pendências</h2><p>3 conferências</p></section></div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"Quatro indicadores formam duas colunas e duas linhas com gaps iguais; os títulos e valores existem no HTML.","quiz":{"question":"O que repeat(2,minmax(0,1fr)) define?","options":["Duas trilhas flexíveis com mínimo zero e partes iguais do espaço flexível disponível.","Duas colunas fixas de1px.","Uma linha com dois itens obrigatoriamente.","A metade exata do viewport para cada item, ignorando gaps."],"answer":0,"explanation":"As trilhas pertencem ao grid container e são dimensionadas considerando o espaço e as restrições da grade."},"exercises":[{"title":"Três colunas","prompt":"Mude repeat para3 e registre a posição do quarto indicador.","hint":"O posicionamento automático preenche as células.","solution":"Os três primeiros ocupam a primeira linha; o quarto inicia a seguinte no fluxo padrão.","criteria":["Identifica a linha do quarto item.","Mantém ordem significativa sem CSS."],"id":1},{"title":"Proporção","prompt":"Compare grid-template-columns:1fr 2fr numa largura conhecida.","hint":"Considere o gap e os mínimos.","solution":"O espaço flexível é dividido com fatores1e2; meça o resultado e explique a diferença entre trilhas e viewport.","criteria":["Registra as medidas.","Não inclui o gap como parte distribuída em fr."],"id":2},{"title":"Conteúdo comprido","prompt":"Coloque um identificador sem espaços num indicador e confira se ele fica disponível.","hint":"A quebra do item complementa o mínimo da trilha.","solution":"Mantenha overflow-wrap:anywhere quando apropriado e confirme que nada fica escondido.","criteria":["O identificador pode ser lido.","Explica a diferença entre trilha e conteúdo."],"id":3}],"source":"https://www.w3.org/TR/css-grid-2/","caution":"","local":true,"hours":4,"minutes":45},{"id":14,"level":5,"title":"Áreas de Grid e ordem do documento","goal":"Organizar regiões sem depender de reordenação semântica.","theory":[{"title":"Áreas dão nome ao layout","text":"Grid-template-areas permite descrever regiões retangulares por nomes. Cada string corresponde a uma linha de trilhas e os nomes repetidos indicam extensão da área. O formato precisa ser coerente: uma área nomeada não pode formar uma figura descontínua."},{"title":"Posicionamento não reescreve o HTML","text":"Grid-area associa uma caixa a uma região visual. Leitura por tecnologia assistiva e foco seguem a estrutura do documento, não um desenho livre das áreas. Preserve uma sequência de navegação e conteúdo que tenha sentido sem CSS."},{"title":"Adaptar a composição","text":"Uma composição com navegação lateral pode virar uma coluna numa largura pequena. O exemplo usa uma base de uma coluna e acrescenta duas colunas quando há espaço. A media query será aprofundada depois; observe agora que muda a grade, não o significado das regiões."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Áreas de Grid e ordem do documento</title>\n<style>\n* { box-sizing: border-box; }\nbody { margin: 0; font-family: system-ui; color: #172b42; }\n.pagina { display: grid; gap: 1rem; padding: 1rem; grid-template-areas: \"cabecalho\" \"menu\" \"conteudo\"; }\nheader { grid-area: cabecalho; }\nnav { grid-area: menu; background: #eaf3fb; padding: 1rem; }\nmain { grid-area: conteudo; min-inline-size: 0; }\na { color: #174a7e; }\n@media (min-width: 42rem) { .pagina { grid-template-columns: 12rem minmax(0, 1fr); grid-template-areas: \"cabecalho cabecalho\" \"menu conteudo\"; } }\n</style>\n</head>\n<body>\n<div class=\"pagina\"><header><h1>Painel de ordens</h1></header><nav aria-label=\"Seções\"><a href=\"#abertas\">Ordens abertas</a></nav><main id=\"abertas\"><h2>Ordens abertas</h2><p>OS-1 aguarda conferência.</p><p>OS-2 aguarda evidências.</p></main></div>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"Em espaço amplo o menu fica ao lado do conteúdo; em espaço estreito as regiões aparecem em uma coluna na ordem do HTML.","quiz":{"question":"Qual afirmação sobre grid-template-areas está correta?","options":["Ela sempre altera a sequência de Tab.","Ela define organização visual, mas não reescreve a ordem do documento para leitura e foco.","Ela permite qualquer área não retangular com o mesmo nome.","Ela elimina a necessidade de elementos semânticos."],"answer":1,"explanation":"O posicionamento visual deve ser consistente com uma estrutura HTML lógica."},"exercises":[{"title":"Mapa de áreas","prompt":"Desenhe em palavras a grade antes e depois de42rem.","hint":"Cada string representa uma linha de trilhas.","solution":"Na base há três áreas empilhadas; na ampla o cabeçalho ocupa ambas as colunas e menu/conteúdo ficam lado a lado.","criteria":["Descreve as duas composições.","Explica os nomes repetidos."],"id":1},{"title":"Ordem sem estilos","prompt":"Desative o CSS e confirme a ordem de título, navegação e conteúdo.","hint":"A estrutura não deve depender da grade.","solution":"O documento continua compreensível; se não estiver, revise primeiro o HTML.","criteria":["A navegação continua identificável.","O destino do link permanece correto."],"id":2},{"title":"Coluna lateral","prompt":"Mude a trilha de12rem para minmax(9rem,14rem) e teste rótulo longo.","hint":"Uma trilha também pode ter limites.","solution":"Registre o espaço usado e confira o conteúdo principal, que continua com mínimo zero.","criteria":["Não perde o rótulo.","Compara o efeito no conteúdo principal."],"id":3}],"source":"https://www.w3.org/TR/css-grid-2/","caution":"","local":true,"hours":4,"minutes":45},{"id":15,"level":5,"title":"Grades fluidas com auto-fit e minmax","goal":"Criar colunas conforme o espaço sem uma lista de tamanhos de aparelhos.","theory":[{"title":"Conteúdo define o limite","text":"Um cartão precisa de uma largura mínima útil para seu texto. Auto-fit repete trilhas conforme elas cabem no container e colapsa trilhas vazias da repetição. O resultado depende do espaço e do mínimo escolhido, não do nome comercial do dispositivo."},{"title":"Proteger o espaço estreito","text":"Minmax(14rem,1fr) sozinho pode causar overflow se o container for menor que14rem. Min(100%,14rem) limita o mínimo pela largura disponível. Isso melhora a base do cartão, mas conteúdo interno ainda pode precisar de quebra e dimensões adequadas."},{"title":"Auto-fit e auto-fill","text":"Ambos calculam repetições automáticas, mas auto-fill mantém trilhas vazias enquanto auto-fit as colapsa depois do posicionamento. Compare com poucos itens e espaço amplo para enxergar a diferença. Escolha conforme o alinhamento esperado, sem decorar uma regra de que um é sempre superior."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Grades fluidas com auto-fit e minmax</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\n.grade { display: grid; gap: 1rem; grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr)); max-inline-size: 65rem; }\n.cartao { padding: 1rem; border: 1px solid #71829a; border-radius: .5rem; overflow-wrap: anywhere; }\n</style>\n</head>\n<body>\n<main><h1>Estoque por item</h1><div class=\"grade\"><article class=\"cartao\"><h2>Item A</h2><p>12 unidades</p></article><article class=\"cartao\"><h2>Item B</h2><p>8 unidades</p></article><article class=\"cartao\"><h2>Item C</h2><p>3 unidades</p></article></div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"Os cartões formam tantas colunas quanto o container permite. Em espaço pequeno, tornam-se uma coluna sem impor14rem além da largura disponível.","quiz":{"question":"Qual é o papel de min(100%,14rem) como mínimo da trilha?","options":["Fixar todas as colunas em100px.","Obrigar14 colunas.","Evitar que o mínimo pretendido ultrapasse a largura disponível num container muito estreito.","Ocultar automaticamente texto longo."],"answer":2,"explanation":"O mínimo pode diminuir com o container; a regra de conteúdo continua sendo uma decisão separada."},"exercises":[{"title":"Limite pelo conteúdo","prompt":"Troque14rem por18rem e observe quantas colunas cabem no mesmo espaço.","hint":"Um mínimo maior permite menos repetições.","solution":"Compare as duas grades na mesma largura e justifique o limite pelo conteúdo do cartão.","criteria":["Registra a mudança de colunas.","Não escolhe o valor apenas por um aparelho específico."],"id":1},{"title":"Trilhas vazias","prompt":"Deixe um cartão e compare auto-fit com auto-fill em espaço amplo.","hint":"A diferença aparece nas trilhas que não recebem itens.","solution":"Auto-fit colapsa as vazias; auto-fill as mantém. O cartão pode ocupar larguras diferentes.","criteria":["Compara o mesmo conteúdo e largura.","Relaciona o resultado às trilhas vazias."],"id":2},{"title":"Menor que o mínimo","prompt":"Teste uma área com menos de14rem e explique por que o min interno importa.","hint":"Compare também minmax(14rem,1fr) em uma cópia.","solution":"A versão com min(100%,14rem) acompanha a área estreita; o mínimo fixo pode excedê-la.","criteria":["Observa as duas versões.","Mantém o texto disponível na solução final."],"id":3}],"source":"https://www.w3.org/TR/css-grid-2/","caution":"","local":true,"hours":4,"minutes":45},{"id":16,"level":6,"title":"Viewport, media queries e base para telas estreitas","goal":"Adicionar adaptações quando o conteúdo realmente pede.","theory":[{"title":"Viewport e documento","text":"A meta viewport permite que navegadores móveis usem uma largura de layout adequada ao dispositivo em vez de uma área virtual ampla. Ela não torna um layout responsivo sozinha. As caixas, os mínimos e as regras de conteúdo ainda precisam responder ao espaço disponível."},{"title":"Base pequena, melhoria quando cabe","text":"Uma base de uma coluna normalmente mantém a leitura em espaço reduzido. A media query acrescenta duas colunas quando o exemplo tem espaço útil. Escolha o ponto pela pressão do conteúdo, não pela ideia de que qualquer valor rotulado tablet descreve todos os aparelhos."},{"title":"Largura não é capacidade","text":"Uma tela grande não garante mouse, e uma pequena não garante toque. Não esconda ações essenciais porque a media query considera a área estreita. Teste também zoom, rótulos longos e preferências de fonte; um viewport de laboratório não representa todas as condições reais."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Viewport, media queries e base para telas estreitas</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; margin: 0; padding: 1rem; color: #172b42; }\nmain { max-inline-size: 60rem; margin-inline: auto; }\n.painel { display: grid; gap: 1rem; }\nsection { padding: 1rem; border: 1px solid #71829a; min-inline-size: 0; }\n@media (min-width: 40rem) { .painel { grid-template-columns: 2fr 1fr; } }\n</style>\n</head>\n<body>\n<main><h1>Painel responsivo</h1><div class=\"painel\"><section><h2>Ordens abertas</h2><p>OS-1: conferir instalação e evidências.</p><p>OS-2: revisar disponibilidade de equipamento.</p></section><section><h2>Estoque</h2><p>12 unidades disponíveis.</p></section></div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"A base tem uma coluna. A partir de40rem de viewport, as seções passam a duas colunas com proporção flexível2para1.","quiz":{"question":"Uma media query de largura consulta o quê neste exemplo?","options":["Sempre o tamanho do texto.","O número de pixels físicos da tela apenas.","Qualquer ancestral com classe painel.","A largura do viewport, não a largura independente de cada cartão."],"answer":3,"explanation":"Consultas de mídia podem usar características do ambiente; esta condição usa a largura do viewport."},"exercises":[{"title":"Ponto necessário","prompt":"Compare o conteúdo imediatamente abaixo e acima de40rem e escolha se o limite é adequado.","hint":"Observe legibilidade e espaço útil.","solution":"Registre a avaliação; altere o limite se os textos ficarem apertados antes da troca.","criteria":["Testa os dois lados do limite.","Justifica a decisão por conteúdo."],"id":1},{"title":"Zoom","prompt":"Use200% de zoom e confira se a composição continua utilizável.","hint":"O espaço em CSS e a quebra podem mudar com zoom.","solution":"A interface deve reorganizar o conteúdo sem remover a seção de estoque.","criteria":["Todas as informações permanecem.","Não depende de esconder seções."],"id":2},{"title":"Rótulo longo","prompt":"Troque Ordens abertas por Ordens aguardando conferência operacional e revise a quebra.","hint":"Permita altura flexível.","solution":"O título quebra naturalmente; evite uma altura fixa que corte o texto.","criteria":["O título aparece completo.","O painel mantém separação entre regiões."],"id":3}],"source":"https://web.dev/learn/design/","caution":"","local":true,"hours":4,"minutes":45},{"id":17,"level":6,"title":"Medidas fluidas com min, max e clamp","goal":"Usar limites para dimensionar sem depender só de viewport units.","theory":[{"title":"Funções expressam limites","text":"Min escolhe o menor valor dentre expressões compatíveis; max escolhe o maior. Clamp estabelece um mínimo, um valor preferido e um máximo. A intenção pode ser uma largura que aproveite a janela sem ultrapassar uma medida confortável de leitura."},{"title":"Tipografia não deve depender só de vw","text":"Uma fonte baseada apenas em vw acompanha o viewport, mas pode ficar minúscula em telas estreitas e interagir mal com necessidades de ampliação. Combine referências relativas à fonte e ao viewport com limites e teste o resultado. Uma fórmula não substitui verificação de zoom e conteúdo."},{"title":"Fluidez não substitui toda mudança","text":"Aumentar ou diminuir valores continuamente pode resolver títulos e espaços, mas uma composição de regiões pode precisar mudar de estrutura. Use funções de tamanho para o que é contínuo e media queries quando há uma alteração de layout com significado."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Medidas fluidas com min, max e clamp</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; margin: 0; padding: clamp(1rem, 4vw, 2.5rem); color: #172b42; }\nmain { inline-size: min(100%, 62ch); margin-inline: auto; }\nh1 { font-size: clamp(1.75rem, 1.25rem + 2vw, 3rem); line-height: 1.15; overflow-wrap: anywhere; }\np { line-height: 1.6; }\n</style>\n</head>\n<body>\n<main><h1>Conferência de ordens de serviço</h1><p>O título e o espaço externo se adaptam dentro de limites. Esta descrição mantém uma coluna de leitura sem pedir uma largura fixa à janela.</p></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"O título e o padding crescem dentro de seus limites; o texto fica numa coluna que cabe no espaço disponível.","quiz":{"question":"O que clamp(1.75rem,1.25rem + 2vw,3rem) faz no font-size?","options":["Limita um tamanho preferido entre um mínimo de1.75rem e um máximo de3rem.","Escolhe sempre2vw.","Garante acessibilidade sem precisar de testes.","Cria três tamanhos usados alternadamente a cada segundo."],"answer":0,"explanation":"Clamp expressa limites; os valores ainda precisam ser avaliados no contexto e com ampliação."},"exercises":[{"title":"Limites observados","prompt":"Teste uma janela estreita e uma larga e inspecione o font-size calculado.","hint":"Compare o preferido com mínimo e máximo.","solution":"Registre os tamanhos encontrados e qual limite, se algum, está ativo em cada caso.","criteria":["Apresenta dois valores calculados.","Relaciona os resultados aos limites."],"id":1},{"title":"Ampliação real","prompt":"Amplie para200% e depois aumente o tamanho padrão de fonte do navegador, se possível.","hint":"São situações diferentes de apenas redimensionar a janela.","solution":"Confira título, quebras e acesso ao texto; revise os limites se houver perda.","criteria":["Registra a condição de teste.","Mantém informação sem cortes."],"id":2},{"title":"Espaço coerente","prompt":"Crie um gap fluido entre duas seções usando clamp(.75rem,2vw,1.5rem).","hint":"A mesma função pode dimensionar espaço.","solution":"Aplique gap num contexto Grid ou Flex, sem esquecer de definir esse contexto.","criteria":["O espaço respeita os limites.","Explica por que gap exige um contexto de layout adequado."],"id":3}],"source":"https://www.w3.org/TR/css-values-4/","caution":"","local":true,"hours":4,"minutes":45},{"id":18,"level":6,"title":"Container queries e componentes reutilizáveis","goal":"Adaptar um descendente pelo espaço de seu container.","theory":[{"title":"O componente pode viver em lugares diferentes","text":"Uma media query observa o viewport; um mesmo cartão pode estar numa coluna estreita ou numa região ampla da mesma página. A size container query permite mudar os descendentes a partir do espaço de um ancestral que estabeleceu contenção adequada."},{"title":"Declare o container certo","text":"Container-type:inline-size prepara consultas da dimensão inline. O nome ordem permite escolher o contexto desejado. A query estiliza descendentes: o cartão interno muda, e não o próprio elemento que está servindo de container para essa consulta."},{"title":"Base e compatibilidade","text":"O exemplo já funciona em uma coluna antes da melhoria. Dentro de supports e da query, ele ganha duas colunas quando há espaço no container. Consulte a compatibilidade para os recursos específicos usados; size queries não significam suporte universal a todas as famílias de container queries."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Container queries e componentes reutilizáveis</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\n.host { inline-size: min(100%, 42rem); margin-block: 1rem; }\n.host.estreito { inline-size: min(100%, 20rem); }\n.cartao { display: grid; gap: 1rem; padding: 1rem; border: 2px solid #174a7e; }\n.cartao h2 { margin: 0; }\n.estado { align-self: start; padding: .4rem; background: #fff2d4; color: #704000; }\n@supports (container-type: inline-size) {\n  .host { container: ordem / inline-size; }\n  @container ordem (min-width: 28rem) { .cartao { grid-template-columns: minmax(0, 1fr) auto; } }\n}\n</style>\n</head>\n<body>\n<main><h1>Mesmo cartão, espaços diferentes</h1><div class=\"host\"><article class=\"cartao\"><div><h2>OS-1</h2><p>Conferir instalação.</p></div><span class=\"estado\">Pendente</span></article></div><div class=\"host estreito\"><article class=\"cartao\"><div><h2>OS-2</h2><p>Revisar evidências.</p></div><span class=\"estado\">Pendente</span></article></div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"Em um viewport suficientemente amplo e com suporte, o primeiro cartão põe status ao lado do texto, e o segundo mantém uma coluna. Em espaço estreito ou sem suporte, ambos seguem a base de uma coluna.","quiz":{"question":"Qual elemento deve estabelecer o contexto consultado neste exemplo?","options":["A própria .cartao consultando seu próprio tamanho para a mesma regra.","O ancestral .host, enquanto a query altera a .cartao descendente.","Qualquer p sem declaração de contenção.","Somente o body, obrigatoriamente."],"answer":1,"explanation":"Size queries consultam um container ancestral elegível; a estrutura separa contexto e componente estilizado."},"exercises":[{"title":"Independência","prompt":"Num viewport largo, altere apenas o tamanho de .host.estreito para32rem.","hint":"Não mude a media query nem a janela.","solution":"O segundo cartão também pode receber a composição em duas colunas quando seu próprio container supera28rem.","criteria":["A mudança depende do host.","Explica por que o viewport ficou igual."],"id":1},{"title":"Fallback","prompt":"Remova temporariamente o bloco supports e avalie a página.","hint":"O estilo base deve ter utilidade própria.","solution":"Ambos os cartões permanecem legíveis em uma coluna; a melhoria é a reorganização, não a existência do conteúdo.","criteria":["Nenhum conteúdo desaparece.","Identifica o comportamento de base."],"id":2},{"title":"Alvo correto","prompt":"Tente aplicar dentro da query uma mudança no próprio host e explique por que esse padrão não consulta o tamanho desse mesmo host para se estilizar.","hint":"A relação é com um ancestral elegível.","solution":"Mantenha um wrapper de contenção e um componente interno como alvo; não dependa de uma autoconsulta de tamanho.","criteria":["Representa ancestral e descendente.","Escolhe um alvo que de fato está dentro do container."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Containment/Container_queries","caution":"","local":true,"hours":4,"minutes":45},{"id":19,"level":7,"title":"Foco visível e controles semânticos","goal":"Percorrer um formulário por teclado e reconhecer a posição do foco.","theory":[{"title":"HTML fornece a interação","text":"Input, button e a possuem comportamentos nativos de interação que uma div estilizada não recebe automaticamente. Um label associado ao campo fornece seu nome e amplia a área de acionamento. CSS deve dar apresentação a essa base, sem apagar a capacidade de utilizá-la."},{"title":"Foco precisa ser perceptível","text":"Focus-visible permite personalizar o indicador quando o navegador determina que ele deve ser mostrado. Preserve o foco nativo onde sua regra não se aplica. Não use outline:none sem um indicador substituto efetivo, e confira se bordas ou overflow de ancestrais cortam seu contorno."},{"title":"Tab e Enter são testes reais","text":"Percorra o documento com Tab e Shift+Tab e veja cada etapa. O formulário desta aula demonstra aparência e validação HTML local; não consulta um banco de ordens. O botão pode enviar os parâmetros ao mesmo documento, sem uma promessa de processamento de backend."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Foco visível e controles semânticos</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\nform { display: grid; gap: .75rem; max-inline-size: 28rem; }\ninput, button { font: inherit; padding: .75rem; border: 2px solid #506780; border-radius: .3rem; }\nbutton { color: #fff; background: #174a7e; cursor: pointer; }\n:is(a, input, button):focus-visible { outline: 3px solid #8a5200; outline-offset: 3px; }\na { color: #174a7e; }\n</style>\n</head>\n<body>\n<main><h1>Consultar OS</h1><p><a href=\"#ajuda\">Ler ajuda</a></p><form method=\"get\"><label for=\"ordem\">ID da ordem</label><input id=\"ordem\" name=\"ordem\" required placeholder=\"OS-1\"><button type=\"submit\">Enviar exemplo</button></form><section id=\"ajuda\"><h2>Ajuda</h2><p>Esta página demonstra o formulário; nenhum banco de dados é consultado.</p></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"O link, o campo e o botão são alcançáveis por teclado. O foco fica visível, e o campo vazio usa a validação nativa ao tentar enviar.","quiz":{"question":"Por que manter um button em vez de uma div apenas com aparência de botão?","options":["Uma div ganha teclado automaticamente ao receber background.","Button não pode receber CSS.","O button já oferece semântica e comportamento nativo de interação.","Qualquer elemento arredondado é um controle nativo."],"answer":2,"explanation":"A aparência não substitui o contrato de interação do HTML."},"exercises":[{"title":"Percurso","prompt":"Use apenas Tab, Shift+Tab e Enter para visitar ajuda, campo e botão.","hint":"Não clique para posicionar o foco durante o teste.","solution":"Registre a sequência e confira que o indicador aparece sem ser cortado.","criteria":["Todos os controles são alcançáveis.","A posição do foco é perceptível em cada etapa."],"id":1},{"title":"Rótulo","prompt":"Clique no texto ID da ordem e explique o efeito da associação for/id.","hint":"Os dois valores precisam coincidir.","solution":"O label associado leva o foco ao campo e fornece seu nome.","criteria":["O campo recebe foco ao acionar o rótulo.","Explica que placeholder não substitui label."],"id":2},{"title":"Aparência nova","prompt":"Altere a cor de fundo do botão e confira hover, foco e contraste.","hint":"A regra de foco precisa continuar perceptível.","solution":"Escolha um par de texto/fundo verificável e mantenha contorno visível; não remova outline para esconder o problema.","criteria":["O rótulo continua legível.","Verifica foco sobre o novo fundo."],"id":3}],"source":"https://www.w3.org/TR/WCAG22/#focus-visible","caution":"","local":true,"hours":4,"minutes":45},{"id":20,"level":7,"title":"Estados de formulário e pseudoclasses","goal":"Representar interação sem confundir validação visual com regra de negócio.","theory":[{"title":"Estados vêm do elemento","text":"Pseudoclasses como checked e disabled representam estados existentes dos controles. Um seletor não cria a validação do servidor nem garante que um usuário tem autorização. O exemplo usa email e required do HTML para uma demonstração local de formato e ausência."},{"title":"Cuidado com erro antecipado","text":"Invalid pode corresponder a um campo vazio obrigatório antes de a pessoa interagir. Mostrar mensagens severas nesse momento pode produzir uma experiência ruim. Defina quando e como um erro será comunicado; a aula destaca a borda para observar o estado, sem alegar um fluxo completo de mensagens de aplicação."},{"title":"Estado tem texto e contraste","text":"Um checkbox marcado pode mudar a superfície de seu rótulo, mas seu texto continua necessário. Um controle desabilitado não deve ser o único lugar de uma informação essencial, pois sua interação e foco diferem dos controles ativos. Use um motivo claro no conteúdo quando a indisponibilidade importa."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Estados de formulário e pseudoclasses</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\nform { display: grid; gap: .8rem; max-inline-size: 28rem; }\ninput[type=\"email\"] { font: inherit; padding: .7rem; border: 2px solid #506780; }\ninput[type=\"email\"]:invalid { border-color: #9a2036; }\ninput[type=\"email\"]:valid { border-color: #17603c; }\n.opcao { display: flex; gap: .6rem; align-items: start; padding: .75rem; border: 1px solid #506780; }\ninput:checked + span { font-weight: 700; }\nbutton { font: inherit; padding: .75rem; }\n:focus-visible { outline: 3px solid #8a5200; outline-offset: 3px; }\n</style>\n</head>\n<body>\n<main><h1>Preferências do relatório</h1><form><label for=\"email\">E-mail para contato</label><input id=\"email\" type=\"email\" required aria-describedby=\"email-ajuda\"><p id=\"email-ajuda\">Exemplo local: observe a validade do formato, sem envio de mensagem.</p><label class=\"opcao\"><input type=\"checkbox\"><span>Incluir ordens concluídas</span></label><button type=\"button\" disabled>Envio indisponível neste exemplo</button></form></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"O campo obrigatório começa inválido e muda de borda ao receber um e-mail no formato aceito pelo navegador. Ao marcar o checkbox, seu texto fica em negrito. O exemplo não envia mensagens.","quiz":{"question":"O que :valid no campo type=email demonstra aqui?","options":["Que o servidor confirmou a propriedade da conta.","Que qualquer texto é seguro para toda aplicação.","Que CSS enviou um e-mail.","Que o valor atende às restrições HTML aplicáveis, sem provar que o endereço existe."],"answer":3,"explanation":"Validação de formato no navegador não confirma existência, autorização ou regras do backend."},"exercises":[{"title":"Formato e existência","prompt":"Digite texto inválido e depois aluno@example.com, registrando a mudança.","hint":"Não há verificação de caixa postal.","solution":"A borda acompanha a validade HTML; a existência real do endereço continua desconhecida.","criteria":["Observa os dois estados.","Não confunde formato com confirmação de endereço."],"id":1},{"title":"Estado marcado","prompt":"Altere a regra do checkbox para acrescentar sublinhado ao texto marcado, mantendo o próprio controle.","hint":"O seletor de irmão usa a estrutura input seguido de span.","solution":"Use input:checked + span { text-decoration:underline; } junto ao peso escolhido.","criteria":["O texto acompanha o estado do checkbox.","Mantém interação nativa por teclado."],"id":2},{"title":"Erro antes da interação","prompt":"Explique por que o campo vazio já tem borda de inválido e proponha uma política de mensagens para uma aplicação futura.","hint":"Required vale desde o estado inicial.","solution":"Diferencie observação do estado de um fluxo de erro após tentativa ou edição; descreva texto de erro associado ao campo.","criteria":["Reconhece a validade inicial.","Propõe uma mensagem além de cor."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Selectors/Pseudo-classes","caution":"","local":true,"hours":4,"minutes":45},{"id":21,"level":7,"title":"Reflow, conteúdo oculto e informação acessível","goal":"Preservar leitura e interação ao mudar apresentação.","theory":[{"title":"Reorganização preserva conteúdo","text":"Reflow permite acompanhar o conteúdo numa área estreita sem exigir rolagem em duas direções para leitura comum. Algumas estruturas, como tabelas complexas, têm exceções contextuais; não use isso como licença para uma página inteira de largura fixa."},{"title":"Esconder tem consequências diferentes","text":"Display:none e visibility:hidden removem normalmente o conteúdo da árvore de acessibilidade, além de seus efeitos distintos no layout. Um padrão visually-hidden pode manter um texto acessível enquanto o retira da apresentação visual, mas ele não deve esconder controles focáveis sem uma estratégia para mostrá-los."},{"title":"Tecnologia assistiva não é uma desculpa para falta de texto","text":"Uma instrução importante costuma precisar estar visível para todas as pessoas. Use texto visualmente oculto apenas quando há uma razão concreta, como completar o nome de links repetidos. A escolha precisa ser testada também com leitura assistiva quando esse recurso estiver disponível."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Reflow, conteúdo oculto e informação acessível</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; margin: 0; padding: 1rem; color: #172b42; }\n.lista { display: grid; gap: 1rem; max-inline-size: 40rem; padding: 0; list-style: none; }\nli { border: 1px solid #71829a; padding: 1rem; overflow-wrap: anywhere; }\na { color: #174a7e; }\n.sr-only { position: absolute; inline-size: 1px; block-size: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }\na:focus-visible { outline: 3px solid #8a5200; outline-offset: 3px; }\n</style>\n</head>\n<body>\n<main><h1>Lista de ordens</h1><ul class=\"lista\"><li><h2>OS-1</h2><p>Instalação aguardando conferência.</p><a href=\"#os1\">Ver detalhes<span class=\"sr-only\"> da OS-1</span></a></li><li><h2>OS-2</h2><p>Revisão com descrição que pode crescer sem uma altura fixa.</p><a href=\"#os2\">Ver detalhes<span class=\"sr-only\"> da OS-2</span></a></li></ul><section id=\"os1\"><h2>Detalhes OS-1</h2><p>Dados fictícios.</p></section><section id=\"os2\"><h2>Detalhes OS-2</h2><p>Dados fictícios.</p></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"A lista se adapta em uma coluna. Os links visíveis dizem Ver detalhes, e seus nomes completos incluem a OS correspondente por meio do texto visualmente oculto.","quiz":{"question":"Quando o texto visualmente oculto ajuda neste exemplo?","options":["Ao completar o nome de links repetidos com o identificador da ordem.","Ao esconder todas as instruções essenciais de quem enxerga.","Ao retirar os links do foco.","Ao substituir o HTML de toda a lista por decoração."],"answer":0,"explanation":"O texto adicional diferencia links sem alterar a estrutura de interação; ainda é necessário testar a experiência acessível."},"exercises":[{"title":"Área estreita","prompt":"Teste uma área de320px de largura em CSS e zoom elevado, verificando texto e links.","hint":"Não imponha width fixa nos cartões.","solution":"A leitura comum deve se reorganizar, com todos os controles alcançáveis.","criteria":["Não perde informações por recorte.","Verifica se existe rolagem horizontal desnecessária."],"id":1},{"title":"Nome completo","prompt":"Inspecione o nome acessível de cada link e compare com o texto visível.","hint":"A árvore de acessibilidade é uma evidência útil.","solution":"Os nomes incluem OS-1 e OS-2, respectivamente; confirme com a ferramenta disponível e registre a limitação se não puder testar leitor de tela.","criteria":["Diferencia os dois nomes.","Não afirma ter testado leitor de tela sem usar um."],"id":2},{"title":"Ocultação diferente","prompt":"Troque sr-only por display:none numa cópia e investigue a diferença na árvore acessível.","hint":"O texto pode deixar de participar do nome.","solution":"Display:none geralmente retira esse texto da árvore; restaure uma solução que mantenha a distinção dos links.","criteria":["Compara os nomes antes e depois.","Escolhe a solução pelo efeito, não só pela aparência."],"id":3}],"source":"https://www.w3.org/TR/WCAG22/#reflow","caution":"","local":true,"hours":4,"minutes":45},{"id":22,"level":8,"title":"Position e o ancestral de referência","goal":"Ancorar decoração ao componente sem retirar informação do fluxo indevidamente.","theory":[{"title":"Posicionamento relativo","text":"Position:relative mantém o elemento no fluxo e permite deslocamentos visuais. Ele também pode estabelecer o containing block para descendentes absolutamente posicionados. O espaço originalmente reservado pelo elemento não se desloca junto com sua aparência."},{"title":"Posicionamento absoluto","text":"Um elemento com position:absolute sai do fluxo normal e usa um containing block apropriado para seus offsets. No exemplo, o badge se ancora ao cartão relativo. Como ele não reserva espaço no fluxo, o cartão precisa reservar espaço suficiente para não sobrepor seu título."},{"title":"Decoração e informação","text":"O badge desta aula contém um status textual já legível. Posicionar no canto não deve impedir sua leitura nem a leitura do título. Para estados com muito texto, um layout Grid ou Flex pode ser mais robusto que um posicionamento absoluto."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Position e o ancestral de referência</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\n.cartao { position: relative; max-inline-size: 30rem; border: 2px solid #174a7e; padding: 4rem 1rem 1rem; }\n.estado { position: absolute; inset-block-start: .75rem; inset-inline-end: .75rem; background: #fff2d4; color: #704000; padding: .4rem .6rem; }\nh2 { margin-block-start: 0; }\n</style>\n</head>\n<body>\n<main><h1>Estado no cartão</h1><article class=\"cartao\"><span class=\"estado\">Pendente</span><h2>OS-1: conferir instalação</h2><p>O espaço superior reserva lugar para o estado.</p></article></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"O estado aparece no canto superior final do cartão, e o título começa abaixo do espaço reservado.","quiz":{"question":"Por que o cartão tem position:relative neste exemplo?","options":["Para tornar todos os filhos invisíveis.","Para estabelecer a referência de posicionamento do badge absoluto descendente.","Para retirar o cartão inteiro do fluxo.","Para obrigar o badge a ocupar espaço no fluxo."],"answer":1,"explanation":"O ancestral relativo oferece um containing block para os offsets do elemento absoluto."},"exercises":[{"title":"Referência removida","prompt":"Retire position:relative do cartão e observe onde o badge se posiciona.","hint":"Ele buscará outro containing block apropriado.","solution":"Registre a nova referência e restaure a ancoragem quando a intenção for manter o badge no cartão.","criteria":["Identifica a mudança de posição.","Explica o papel do ancestral."],"id":1},{"title":"Texto de estado longo","prompt":"Troque Pendente por Confirmação operacional pendente e teste uma área estreita.","hint":"O espaço reservado pode deixar de ser suficiente.","solution":"Documente a limitação e experimente usar Grid ou fluxo normal para um estado variável.","criteria":["Não deixa título e estado sobrepostos.","Escolhe uma solução adequada ao texto variável."],"id":2},{"title":"Deslocamento relativo","prompt":"Aplique inset-block-start:.5rem ao próprio cartão mantendo relative e observe o espaço que ele reservava.","hint":"O fluxo usa a posição original.","solution":"O cartão se desloca visualmente, mas não reposiciona automaticamente os vizinhos pelo novo desenho.","criteria":["Distingue desenho e espaço no fluxo.","Compara o comportamento de um elemento seguinte."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/position","caution":"","local":true,"hours":4,"minutes":45},{"id":23,"level":8,"title":"Sticky, região de rolagem e foco","goal":"Manter contexto de uma lista sem encobrir seu conteúdo.","theory":[{"title":"Sticky depende de limites","text":"Position:sticky combina participação no fluxo com contenção do deslocamento por um inset. Ele atua em relação ao ancestral de rolagem pertinente e continua limitado pelo seu bloco de contenção. Sem espaço para rolar ou sem inset, a mudança esperada pode não aparecer."},{"title":"Rolagem precisa de um contrato","text":"Overflow:auto com altura máxima cria uma região de rolagem quando o conteúdo excede esse limite. Pense se a região precisa ser independente ou se a página inteira poderia rolar; muitas áreas internas podem dificultar o uso por teclado e a orientação."},{"title":"Cabeçalho também pode atrapalhar","text":"Um elemento fixado sobre o conteúdo pode ocultar destinos de âncora ou indicadores de foco. Scroll-margin ajuda a deixar espaço ao navegar para um alvo. Faça testes reais de foco e rolagem, especialmente quando a altura do cabeçalho muda com texto ou zoom."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Sticky, região de rolagem e foco</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\na { color: #174a7e; }\n.regiao { max-block-size: 17rem; overflow: auto; border: 2px solid #174a7e; max-inline-size: 36rem; }\n.regiao h2 { position: sticky; inset-block-start: 0; margin: 0; padding: 1rem; background: #eaf3fb; border-block-end: 1px solid #71829a; }\n.ordem { padding: 1.25rem; border-block-end: 1px solid #a9b8c8; scroll-margin-block-start: 5rem; }\n:focus-visible { outline: 3px solid #8a5200; outline-offset: -3px; }\n</style>\n</head>\n<body>\n<main><h1>Lista com contexto</h1><p><a href=\"#os4\">Ir para OS-4</a></p><section class=\"regiao\" tabindex=\"0\" aria-label=\"Lista rolável de ordens\"><h2>Ordens abertas</h2><article class=\"ordem\" id=\"os1\"><h3>OS-1</h3><p>Instalação</p></article><article class=\"ordem\" id=\"os2\"><h3>OS-2</h3><p>Revisão</p></article><article class=\"ordem\" id=\"os3\"><h3>OS-3</h3><p>Conferência</p></article><article class=\"ordem\" id=\"os4\"><h3>OS-4</h3><p>Verificação final</p></article></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"A região interna pode rolar; seu título permanece no topo durante parte da rolagem e continua dentro da própria região. O link leva à OS-4.","quiz":{"question":"Por que um sticky pode não parecer se mover em um teste?","options":["Porque sticky exige JavaScript em todos os casos.","Porque sticky sempre usa a janela inteira como referência.","Pode faltar um inset, espaço de rolagem ou haver limites do ancestral que restringem o efeito.","Porque todo elemento sticky sai completamente do fluxo."],"answer":2,"explanation":"O comportamento depende do contexto de rolagem e dos limites, não só da palavra sticky."},"exercises":[{"title":"Limite de rolagem","prompt":"Remova max-block-size da região e compare o efeito observado.","hint":"O container pode deixar de ter rolagem interna.","solution":"Registre a mudança no contexto de rolagem e não conclua que sticky está quebrado apenas por não repetir a mesma aparência.","criteria":["Identifica o elemento que rola.","Relaciona o limite ao comportamento."],"id":1},{"title":"Teclado","prompt":"Use Tab para focar a região e tente rolá-la com teclado, sem mouse.","hint":"O tabindex torna a região explicitamente focável.","solution":"Confira indicador de foco, nome da região e acesso a todo conteúdo; registre diferenças do navegador.","criteria":["O conteúdo final pode ser alcançado.","O foco não fica invisível."],"id":2},{"title":"Destino visível","prompt":"Acione Ir para OS-4 e confira se o cabeçalho encobre o título da ordem.","hint":"Scroll-margin reserva espaço para navegação ao alvo.","solution":"Ajuste o scroll-margin conforme a altura real do cabeçalho, incluindo zoom e texto maior.","criteria":["O título de destino permanece visível.","Testa uma condição de ampliação."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/position","caution":"","local":true,"hours":4,"minutes":45},{"id":24,"level":8,"title":"Stacking contexts e z-index","goal":"Resolver uma sobreposição a partir dos contextos de empilhamento.","theory":[{"title":"Números têm contexto","text":"Z-index não estabelece uma competição global de todos os elementos da página. Elementos podem formar stacking contexts e seus descendentes são empilhados dentro desse contexto. Um filho com número alto não escapa automaticamente do contexto do pai para superar um contexto irmão."},{"title":"Origens de contexto","text":"Entre as causas de novos contextos estão certas combinações de position e z-index, opacity menor que1 e transform diferente de none. Nem toda propriedade que parece decorativa é neutra para empilhamento. Inspecione os ancestrais quando um menu permanece atrás de outro painel."},{"title":"Corrigir a relação certa","text":"No exemplo, o badge da primeira caixa tem z-index:999, mas seu contexto pai está abaixo da segunda caixa. A correção pode ser remover um contexto desnecessário ou alterar a hierarquia das camadas. Para um diálogo real, semântica, foco e top layer também importam; desenhar uma caixa flutuante não implementa tudo isso."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Stacking contexts e z-index</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\n.cenario { position: relative; max-inline-size: 30rem; min-block-size: 14rem; }\n.painel { position: relative; padding: 1rem; min-block-size: 8rem; border: 2px solid #174a7e; background: #eaf3fb; }\n.primeiro { z-index: 1; }\n.segundo { z-index: 2; margin-block-start: -1rem; margin-inline-start: 3rem; background: #fff2d4; }\n.badge { position: absolute; z-index: 999; inset-block-end: -.5rem; inset-inline-end: 1rem; padding: .5rem; color: #fff; background: #5b246b; }\n</style>\n</head>\n<body>\n<main><h1>Camadas em observação</h1><div class=\"cenario\"><section class=\"painel primeiro\"><h2>Contexto1</h2><span class=\"badge\">Filho com999</span></section><section class=\"painel segundo\"><h2>Contexto2</h2><p>Este painel fica acima do contexto1.</p></section></div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Compare larguras, conteúdo e regras nas ferramentas de desenvolvimento.","expected":"A segunda caixa sobrepõe parte da primeira; o badge com999 pode ficar encoberto porque está limitado ao contexto1.","quiz":{"question":"Por que aumentar apenas o z-index do badge pode não colocá-lo acima da segunda caixa?","options":["Porque999 é um valor inválido em CSS.","Porque z-index sempre ignora elementos posicionados.","Porque toda caixa precisa de um ID.","Ele continua dentro de um stacking context pai que está abaixo do contexto irmão."],"answer":3,"explanation":"A comparação entre contextos irmãos acontece antes da composição dos descendentes de cada contexto."},"exercises":[{"title":"Camada do pai","prompt":"Mude o z-index do primeiro painel para3 e compare a relação entre as caixas.","hint":"A comparação relevante está nos pais.","solution":"O contexto do primeiro passa a ser empilhado acima do segundo neste cenário controlado.","criteria":["Registra a mudança de sobreposição.","Explica por que mudou o pai, não só o filho."],"id":1},{"title":"Nova causa","prompt":"Remova o z-index do primeiro painel e experimente opacity:.99, inspecionando a criação de contexto.","hint":"Transparência parcial pode criar um contexto.","solution":"Documente o contexto criado e seus efeitos; não use opacity apenas para tentar consertar uma camada.","criteria":["Identifica uma causa concreta.","Não trata z-index como comparação global."],"id":2},{"title":"Diagnóstico","prompt":"Escreva um roteiro de inspeção para um menu cortado ou atrás de outro painel.","hint":"Corte e empilhamento podem ser problemas diferentes.","solution":"Procure overflow que recorta, containing blocks, contextos ancestrais e a relação com o painel vizinho antes de alterar números.","criteria":["Distingue recorte de empilhamento.","Propõe uma verificação de ancestral antes do ajuste."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Positioned_layout/Stacking_context","caution":"","local":true,"hours":4,"minutes":45},{"id":25,"level":9,"title":"Custom properties, escopo e temas","goal":"Reutilizar decisões visuais sem confundir variável CSS com substituição de texto global.","theory":[{"title":"Valores com intenção","text":"Custom properties como --superficie e --texto guardam valores usados por outras declarações. Nomear a função de uma cor permite trocar sua aparência sem renomear cada componente. Elas participam da cascata e, por padrão, são herdadas por descendentes."},{"title":"Escopo do tema","text":"Definir tokens em root fornece uma base; redefini-los num ancestral cria uma região temática. O mesmo cartão pode usar os valores herdados sem duplicar sua regra inteira. Isso não obriga todos os estados a terem contraste adequado: cada par efetivo precisa ser verificado."},{"title":"Fallback tem um papel específico","text":"Var(--espaco,1rem) pode usar o fallback se a custom property estiver ausente ou em um estado que impeça sua substituição. Ele não é um validador geral do valor final: uma variável definida com um valor incompatível com padding pode invalidar a declaração no momento de cálculo, em vez de escolher automaticamente1rem."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Custom properties, escopo e temas</title>\n<style>\n:root { --superficie: #fff; --texto: #172b42; --borda: #71829a; --espaco: 1rem; }\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; background: #edf2f8; }\n.tema-escuro { --superficie: #172b42; --texto: #f3f7fc; --borda: #a5bed8; }\n.cartao { max-inline-size: 32rem; margin-block: 1rem; padding: var(--espaco, 1rem); color: var(--texto); background: var(--superficie); border: 2px solid var(--borda); border-radius: .5rem; }\n</style>\n</head>\n<body>\n<main><h1>Temas por região</h1><section class=\"cartao\"><h2>OS-1</h2><p>Cartão com tema de base.</p></section><div class=\"tema-escuro\"><section class=\"cartao\"><h2>OS-2</h2><p>O componente herda outro conjunto de valores.</p></section></div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"O mesmo estilo de cartão aparece numa versão clara e outra escura por meio dos valores herdados dos tokens.","quiz":{"question":"Por que o cartão dentro de .tema-escuro muda sem uma nova regra .cartao?","options":["Ele usa custom properties redefinidas no ancestral e herdadas pelo componente.","Porque o navegador reconhece automaticamente o nome tema-escuro.","Porque classes sempre alteram texto HTML.","Porque toda custom property ignora a cascata."],"answer":0,"explanation":"As custom properties participam da cascata e podem mudar por escopo."},"exercises":[{"title":"Espaço local","prompt":"Defina --espaco:1.5rem apenas no ancestral do cartão escuro.","hint":"O componente usa var(--espaco).","solution":"Somente o cartão dessa região recebe o novo padding, mantendo a regra do componente.","criteria":["Compara os dois paddings.","Explica onde o token foi redefinido."],"id":1},{"title":"Token ausente","prompt":"Remova a declaração de --espaco da base e observe o fallback.","hint":"O segundo argumento de var fornece a alternativa.","solution":"Padding usa1rem enquanto a custom property não estiver definida no escopo.","criteria":["Identifica o valor usado.","Distingue ausência de valor de qualquer erro possível."],"id":2},{"title":"Contraste do tema","prompt":"Meça os pares texto/superfície dos dois temas e inclua um link em cada cartão.","hint":"O link também precisa de uma cor apropriada.","solution":"Crie um token de link se necessário e teste foco/contraste em ambos os escopos.","criteria":["Verifica texto e link nos dois temas.","Não assume que trocar apenas o fundo resolve todo o tema."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Cascading_variables/Using_custom_properties","caution":"","local":true,"hours":4,"minutes":45},{"id":26,"level":9,"title":"Transições e preferências de movimento","goal":"Relacionar uma transição a um estado sem prejudicar foco ou movimento reduzido.","theory":[{"title":"Uma mudança entre valores","text":"Transition descreve a interpolação quando uma propriedade muda entre estados compatíveis. O hover do exemplo muda cor de fundo; o foco tem um indicador independente. Sem uma mudança de valor, uma declaração de transition não cria uma animação por si só."},{"title":"Escolher o que muda","text":"Transition:all pode animar propriedades adicionadas futuramente sem que isso tenha sido planejado. Liste as propriedades desejadas e use durações pequenas que ajudem a perceber o estado. Alterações de layout e efeitos complexos podem ter custo; não há uma garantia de desempenho baseada apenas numa receita."},{"title":"Movimento opcional","text":"A base funciona sem transição nem deslocamento. Dentro de prefers-reduced-motion:no-preference, o exemplo acrescenta uma transição e pequeno deslocamento no hover. A preferência por menos movimento não deve remover a informação de que o link está focado ou disponível."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Transições e preferências de movimento</title>\n<style>\nbody { font-family: system-ui; padding: 1.5rem; color: #172b42; }\n.acao { display: inline-block; padding: .85rem 1rem; border-radius: .5rem; color: #fff; background: #174a7e; text-decoration: none; }\n.acao:hover { background: #103a65; }\n.acao:focus-visible { outline: 3px solid #8a5200; outline-offset: 4px; }\n@media (prefers-reduced-motion: no-preference) {\n .acao { transition: background-color 160ms ease, transform 160ms ease; }\n .acao:hover { transform: translateY(-2px); }\n}\n</style>\n</head>\n<body>\n<main><h1>Feedback de navegação</h1><a class=\"acao\" href=\"#detalhes\">Ver detalhes da OS-1</a><section id=\"detalhes\"><h2>Detalhes da OS-1</h2><p>O link navega para conteúdo real desta página.</p></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"O hover escurece o link e, sem preferência por movimento reduzido, ele pode subir2px com uma transição curta. O foco por teclado tem contorno em qualquer modo.","quiz":{"question":"Por que listar propriedades em transition em vez de usar all indiscriminadamente?","options":["Porque all nunca é uma sintaxe válida.","Para controlar quais mudanças terão interpolação, inclusive quando o componente evoluir.","Porque qualquer transição exige JavaScript.","Porque listar propriedades dispensa verificar desempenho."],"answer":1,"explanation":"Uma lista explícita evita efeitos incidentais em propriedades que não foram planejadas para animar."},"exercises":[{"title":"Preferência do sistema","prompt":"Ative ou emule movimento reduzido e compare o link.","hint":"Use o painel de rendering do navegador se disponível.","solution":"O deslocamento e a transição não são aplicados nessa condição; navegação e foco continuam disponíveis.","criteria":["Compara as duas condições.","Não perde o indicador de foco."],"id":1},{"title":"Estado sem mouse","prompt":"Use Tab e Enter, sem hover, para acessar o destino.","hint":"Foco e hover são estados diferentes.","solution":"O contorno indica o link focado e Enter chega à seção correspondente.","criteria":["O destino é alcançado por teclado.","Não depende da animação para entender a ação."],"id":2},{"title":"Mudança planejada","prompt":"Acrescente uma borda permanente ao link, sem animar o tamanho da caixa.","hint":"Reserve a borda no estado base.","solution":"Use border:2px solid com cor apropriada; se quiser interpolar cor, liste border-color sem alterar a espessura entre estados.","criteria":["A caixa não salta por borda adicionada no hover.","A lista de propriedades continua explícita."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/At-rules/%40media/prefers-reduced-motion","caution":"","local":true,"hours":4,"minutes":45},{"id":27,"level":9,"title":"Keyframes, duração e animação que termina","goal":"Criar uma entrada breve com conteúdo disponível sem animação.","theory":[{"title":"Keyframes descrevem etapas","text":"Uma regra keyframes define valores em fases de uma animação. Animation associa nome, duração e outras características ao elemento. O exemplo termina após uma execução; ele não usa uma repetição infinita para chamar atenção sobre um status estático."},{"title":"Conteúdo não depende da execução","text":"A informação Concluída está no HTML desde o início. A animação é uma entrada visual, não uma prova de que uma operação de backend terminou. Evite usar animação para simular carregamento ou sucesso de algo que não foi realizado."},{"title":"Preferência e controle","text":"Prefers-reduced-motion:reduce desativa a animação no exemplo e deixa o selo no estado base visível. Em sistemas reais, movimento contínuo pode exigir mecanismos adicionais de pausa e outras revisões de acessibilidade. Uma preferência de movimento não substitui todo o cuidado com flashes ou conteúdo que se move sozinho."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Keyframes, duração e animação que termina</title>\n<style>\nbody { font-family: system-ui; padding: 1.5rem; color: #172b42; }\n.selo { display: inline-block; padding: .7rem 1rem; border: 2px solid #17603c; background: #e8f6ee; color: #155534; animation: entrada 450ms ease-out 1; }\n@keyframes entrada { from { opacity: 0; transform: translateY(.3rem); } to { opacity: 1; transform: translateY(0); } }\n@media (prefers-reduced-motion: reduce) { .selo { animation: none; } }\n</style>\n</head>\n<body>\n<main><h1>Status de exemplo</h1><p class=\"selo\">Concluída — estado fictício do material</p><p>O texto está disponível sem depender da animação.</p></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"O selo entra brevemente e permanece visível. Com movimento reduzido, aparece diretamente sem o deslocamento animado.","quiz":{"question":"O que acontece se animation:none for aplicada neste exemplo?","options":["O conteúdo HTML é apagado.","A classe deixa de existir.","O texto continua visível com os estilos de base, sem executar os keyframes.","O status de backend é cancelado."],"answer":2,"explanation":"A informação e os estilos de base não dependem de uma animação em execução."},"exercises":[{"title":"Tempo percebido","prompt":"Compare450ms com150ms e registre se a entrada ajuda ou atrapalha a leitura.","hint":"A duração deve servir a um objetivo observável.","solution":"Escolha uma duração justificada ou remova a animação se não acrescentar informação útil.","criteria":["Compara duas condições.","Não transforma a entrada em uma distração contínua."],"id":1},{"title":"Base sem efeito","prompt":"Remova toda a declaração animation e os keyframes numa cópia.","hint":"O estilo base precisa ser suficiente.","solution":"O selo conserva texto, borda, cores e espaço; apenas a entrada desaparece.","criteria":["O conteúdo continua visível.","Distingue estado do domínio e efeito visual."],"id":2},{"title":"Verificação de preferência","prompt":"Emule reduce e observe a regra vencedora no painel de estilos.","hint":"A media query precisa estar ativa e vencer a declaração pertinente.","solution":"Registre animation:none como valor usado para a condição e confira que o selo não se desloca.","criteria":["Identifica a condição de mídia.","Confere o resultado em vez de apenas ler o CSS."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/At-rules/%40media/prefers-reduced-motion","caution":"","local":true,"hours":4,"minutes":45},{"id":28,"level":10,"title":"Cascade layers e ordem de arquitetura","goal":"Definir prioridades previsíveis antes de competir por especificidade.","theory":[{"title":"Camadas são uma etapa da cascata","text":"A declaração inicial layer base,components,overrides estabelece uma ordem para camadas. Para declarações normais da mesma origem, camadas posteriores têm precedência sobre anteriores antes de comparar especificidade. Isso permite uma regra de variante simples vencer uma regra de componente mais específica em outra camada."},{"title":"Regras fora de camada","text":"Uma declaração normal do autor fora de qualquer camada tem prioridade sobre declarações normais do autor em camadas. Não copie uma regra para fora das camadas sem considerar esse efeito. Organize também CSS de terceiros quando ele faz parte da aplicação."},{"title":"Importância inverte a ordem de camadas","text":"Com declarações importantes a prioridade entre camadas se inverte: as primeiras camadas recebem maior prioridade e declarações importantes em camadas têm precedência sobre as importantes sem camada nessa origem. Não é necessário usar important neste exemplo; conhecer a exceção evita explicar a cascata de forma incompleta."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Cascade layers e ordem de arquitetura</title>\n<style>\n@layer base, components, overrides;\n@layer base { body { font-family: system-ui; padding: 1rem; color: #172b42; } a { color: #174a7e; } }\n@layer components { .painel .acao { display: inline-block; padding: .8rem 1rem; color: #fff; background: #174a7e; border-radius: .4rem; text-decoration: none; } }\n@layer overrides { .acao { background: #5b246b; } }\n.acao:focus-visible { outline: 3px solid #8a5200; outline-offset: 3px; }\n</style>\n</head>\n<body>\n<main class=\"painel\"><h1>Prioridades declaradas</h1><a class=\"acao\" href=\"#entrega\">Conferir entrega</a><section id=\"entrega\"><h2>Entrega</h2><p>A variante da última camada normal define o fundo roxo.</p></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"O link usa fundo roxo de overrides, mesmo com seletor mais simples que o da camada components.","quiz":{"question":"Por que .acao em overrides vence .painel .acao em components no fundo?","options":["Qualquer seletor menor é sempre mais forte.","A palavra overrides é uma palavra-chave com cor especial.","As camadas eliminam todas as outras etapas da cascata.","A prioridade entre camadas normais é resolvida antes da especificidade."],"answer":3,"explanation":"A ordem declarada das camadas decide esse conflito de regras normais do mesmo autor."},"exercises":[{"title":"Camada posterior","prompt":"Troque a ordem inicial para base,overrides,components e preveja o fundo.","hint":"Muda a prioridade de declarações normais entre camadas.","solution":"Components passa a ter maior prioridade nessa disputa; o fundo fica azul.","criteria":["Confirma o valor calculado.","Explica a etapa da cascata que decidiu."],"id":1},{"title":"Fora das camadas","prompt":"Acrescente ao fim .acao { background:#155534; } fora de layer.","hint":"Declarações normais sem camada têm prioridade sobre as normais em camadas nessa origem.","solution":"O fundo fica verde no cenário controlado. Registre por que mover a regra mudou sua prioridade.","criteria":["Identifica a regra sem camada.","Não atribui o resultado apenas à ordem textual."],"id":2},{"title":"Regra de equipe","prompt":"Escreva uma convenção para base,components e overrides sem usar important como solução padrão.","hint":"Inclua onde entram variantes e integrações.","solution":"Defina propósito e prioridade de cada camada, mantendo exceções documentadas.","criteria":["A convenção explica responsabilidades.","Reconhece o efeito de regras normais fora de camada."],"id":3}],"source":"https://www.w3.org/TR/css-cascade-5/","caution":"","local":true,"hours":4,"minutes":45},{"id":29,"level":10,"title":"Especificidade manejável com where e is","goal":"Construir seletores sem tornar toda variação uma disputa.","theory":[{"title":"Agrupar não significa a mesma força","text":"Is e where permitem agrupar alternativas, mas diferem na especificidade. Where e seus argumentos contribuem com especificidade zero. Is usa a maior especificidade entre seus argumentos, mesmo que o ramo de maior peso não seja o que encontrou o elemento no caso observado."},{"title":"Defaults fáceis de substituir","text":"Where pode ajudar a escrever padrões de baixo peso, deixando classes locais ajustar o componente sem recorrer a important. Ainda é necessário considerar origem, importância e camadas: especificidade é só uma etapa, não toda a resolução."},{"title":"Contrato antes de seletor enorme","text":"Um seletor que depende de muitos ancestrais e IDs torna o componente sensível à estrutura da página. Prefira classes ou atributos com função clara e um alcance deliberado. Escrever um seletor menor não é uma garantia automática de desempenho, mas pode tornar o contrato mais compreensível."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Especificidade manejável com where e is</title>\n<style>\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\n:where(.cartao) { padding: 1rem; border: 2px solid #71829a; background: #eaf3fb; max-inline-size: 30rem; margin-block: 1rem; }\n.aviso { background: #fff2d4; }\n:is(.cartao, .resumo) h2 { margin-block-start: 0; }\n</style>\n</head>\n<body>\n<main><h1>Padrão e variante</h1><article class=\"cartao\"><h2>OS-1</h2><p>Estilo de base.</p></article><article class=\"cartao aviso\"><h2>OS-2</h2><p>Variante com outra superfície.</p></article></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"Os cartões recebem espaçamento e borda do padrão; a classe aviso troca a superfície do segundo.","quiz":{"question":"Qual diferença importa entre :where(.cartao) e :is(.cartao,#principal)?","options":["Where tem especificidade zero; is assume a maior especificidade de seus argumentos.","Ambos sempre têm exatamente a especificidade de um elemento.","Where sempre vence is por ser mais recente.","Is cria automaticamente um ID no HTML."],"answer":0,"explanation":"Where facilita padrões leves; incluir um ID numa lista de is pode elevar o peso do seletor inteiro."},"exercises":[{"title":"Variação simples","prompt":"Adicione uma variante .compacto com padding:.5rem a um cartão.","hint":"O padrão de where tem peso zero.","solution":"A classe local pode alterar o padding no cenário controlado sem duplicar ancestrais.","criteria":["A variante só altera o cartão pretendido.","Explica por que não precisou de important."],"id":1},{"title":"Peso oculto","prompt":"Substitua um agrupamento por :is(.cartao,#principal) e compare a especificidade prevista.","hint":"O maior argumento determina a contribuição de is.","solution":"Registre que o ID eleva o peso mesmo quando o elemento corresponde ao ramo .cartao; evite esse aumento se não fizer parte do contrato.","criteria":["Calcula a contribuição correta.","Distingue correspondência e especificidade da lista."],"id":2},{"title":"Dependência de estrutura","prompt":"Compare .pagina main .lista article.cartao p com .cartao__descricao para um componente reutilizável.","hint":"Pense em mudar o cartão para outra região.","solution":"Uma classe própria pode reduzir dependência de ancestrais, desde que seja aplicada ao elemento certo e não vaze para outros contratos.","criteria":["Explica uma mudança de estrutura tolerada.","Não afirma que seletor curto resolve qualquer arquitetura."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Selectors/:where","caution":"","local":true,"hours":4,"minutes":45},{"id":30,"level":10,"title":"Componentes, variantes e estados relacionais","goal":"Definir limites de estilo e melhorias sem depender de estrutura oculta.","theory":[{"title":"Um componente tem um contrato","text":"Um campo pode conter label, input e instrução, com classes que representam suas partes. Uma variante deve mudar aspectos previstos, como densidade ou destaque, sem redefinir toda a estrutura. Documentar o HTML esperado ajuda a explicar por que um seletor de irmão ou descendência funciona."},{"title":"Estado existente pode ser consultado","text":"Has permite selecionar um elemento a partir de condições em seus descendentes ou relações. No exemplo, o campo pode receber destaque quando contém um input em foco visível. Isso não move foco, não valida o domínio e não substitui a borda de foco do próprio controle."},{"title":"Melhoria progressiva","text":"O estilo base é suficiente para entender e usar o campo. A regra relacional fica dentro de supports selector(:has(*)); se a condição não for suportada, a interface continua funcional. Teste a funcionalidade concreta em vez de transformar um verificador de sintaxe em promessa de toda compatibilidade."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Componentes, variantes e estados relacionais</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\n.campo { max-inline-size: 30rem; padding: 1rem; border: 2px solid #71829a; border-radius: .5rem; }\n.campo__rotulo { display: block; font-weight: 700; margin-block-end: .5rem; }\n.campo__entrada { inline-size: 100%; padding: .7rem; font: inherit; border: 2px solid #506780; }\n.campo__ajuda { line-height: 1.5; }\n.campo--compacto { padding: .6rem; }\n.campo__entrada:focus-visible { outline: 3px solid #8a5200; outline-offset: 3px; }\n@supports selector(:has(*)) { .campo:has(.campo__entrada:focus-visible) { background: #eaf3fb; border-color: #174a7e; } }\n</style>\n</head>\n<body>\n<main><h1>Campo como componente</h1><div class=\"campo campo--compacto\"><label class=\"campo__rotulo\" for=\"busca\">Identificador da OS</label><input class=\"campo__entrada\" id=\"busca\" aria-describedby=\"busca-ajuda\"><p class=\"campo__ajuda\" id=\"busca-ajuda\">Exemplo de apresentação; digitar não consulta um serviço.</p></div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"O campo tem uma base compacta e foco visível. Com suporte a has, a superfície do componente ganha destaque quando o input tem foco visível.","quiz":{"question":"Qual é a garantia importante do fallback neste exemplo?","options":["A ausência de has impede todo HTML de funcionar.","O input e seu foco continuam utilizáveis mesmo sem a melhoria com has.","Supports implementa automaticamente a funcionalidade em navegadores antigos.","Has torna o input uma consulta real de API."],"answer":1,"explanation":"Melhoria progressiva acrescenta apresentação sobre uma base funcional e não exige a nova regra para interação essencial."},"exercises":[{"title":"Sem melhoria","prompt":"Retire o bloco supports e percorra o campo com teclado.","hint":"O foco do input está fora da condição.","solution":"O input conserva label, instrução e indicador de foco; só perde o destaque do wrapper.","criteria":["A interação permanece disponível.","Identifica exatamente a melhoria removida."],"id":1},{"title":"Duas instâncias","prompt":"Crie outro campo com IDs exclusivos e verifique se o foco destaca apenas o componente correspondente.","hint":"Não duplique o mesmo id nos controles.","solution":"Use outro par for/id e outra instrução associada; o seletor relacional age na instância que contém o foco.","criteria":["Os rótulos apontam para campos corretos.","O estilo não vaza para o outro wrapper."],"id":2},{"title":"Contrato escrito","prompt":"Descreva as partes e a variante compacto sem usar a posição do componente na página.","hint":"Documente classes e relações necessárias.","solution":"Explique o wrapper, o rótulo, a entrada, a ajuda e o efeito restrito da variante.","criteria":["O contrato permite outra instância.","Não depende de um ancestral externo arbitrário."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/At-rules/%40supports","caution":"","local":true,"hours":4,"minutes":45},{"id":31,"level":11,"title":"Propriedades lógicas e direção de escrita","goal":"Separar início e fim lógicos de esquerda e direita físicas.","theory":[{"title":"Direção muda a referência","text":"Inline e block se relacionam ao modo de escrita. Em um texto horizontal LTR, o início inline corresponde à esquerda; em RTL, corresponde à direita. Propriedades como padding-inline e border-inline-start podem expressar a intenção sem duplicar regras físicas para cada direção."},{"title":"Escolher a intenção correta","text":"Nem toda medida deve ser lógica: uma posição realmente física de uma ilustração pode ser descrita como tal. Para borda de destaque no início da leitura, uma propriedade lógica costuma representar melhor a intenção. Avalie a função, não faça apenas uma troca mecânica de palavras."},{"title":"RTL não é tradução","text":"Dir muda a direção do texto e do layout em contextos pertinentes, mas não traduz conteúdo nem resolve todos os detalhes de números e textos mistos. Use conteúdo real e revisão por quem conhece o idioma na entrega final. O exemplo serve para observar a geometria com os mesmos dados fictícios."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Propriedades lógicas e direção de escrita</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\n.cartao { max-inline-size: 32rem; margin-block: 1rem; padding-block: 1rem; padding-inline: 1.5rem; border: 1px solid #71829a; border-inline-start: .5rem solid #174a7e; text-align: start; }\nh2 { margin-block-start: 0; }\n</style>\n</head>\n<body>\n<main><h1>Direção e início lógico</h1><section class=\"cartao\" dir=\"ltr\"><h2>Direção LTR</h2><p><bdi>OS-1</bdi>: dados fictícios para observar o layout.</p></section><section class=\"cartao\" dir=\"rtl\"><h2>Direção RTL</h2><p><bdi>OS-2</bdi>: mesmos dados para comparação geométrica.</p></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"A borda de início e o alinhamento de texto aparecem em lados opostos conforme dir; o conteúdo não é traduzido automaticamente.","quiz":{"question":"Qual propriedade descreve uma borda no início da direção inline?","options":["border-left em todo modo de escrita.","font-direction.","border-inline-start.","grid-auto-flow obrigatoriamente."],"answer":2,"explanation":"A propriedade lógica acompanha a direção de escrita em vez de fixar sempre um lado físico."},"exercises":[{"title":"Comparação física","prompt":"Troque border-inline-start por border-left e compare as duas regiões.","hint":"A propriedade física não acompanha dir.","solution":"A borda esquerda permanece à esquerda em ambas; isso muda a intenção para a região RTL.","criteria":["Registra os dois lados.","Explica a diferença de intenção."],"id":1},{"title":"Espaçamento","prompt":"Use margin-inline-start:1rem em um elemento interno e teste dir nos dois casos.","hint":"O início inline muda com a direção.","solution":"A separação acompanha o início lógico; confirme o efeito visual no contexto.","criteria":["Compara LTR e RTL.","Não trata início como sinônimo universal de esquerda."],"id":2},{"title":"Conteúdo real","prompt":"Liste o que ainda precisaria ser revisado ao localizar o painel para um idioma RTL.","hint":"CSS não traduz rótulos nem garante leitura de todo texto misto.","solution":"Inclua tradução, revisão de rótulos e ícones direcionais, números e teste com pessoas que leem esse idioma.","criteria":["Distingue direção de tradução.","Aponta ao menos dois testes além da borda."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Logical_properties_and_values","caution":"","local":true,"hours":4,"minutes":45},{"id":32,"level":11,"title":"Subgrid com base independente","goal":"Alinhar partes de cartões em trilhas compartilhadas sem exigir a melhoria.","theory":[{"title":"Grades aninhadas normalmente são independentes","text":"Um filho que vira grid cria suas próprias trilhas. Mesmo que dois cartões usem a mesma quantidade de linhas, seus conteúdos podem produzir alturas diferentes. Subgrid permite que um item de grade adote trilhas do grid pai na dimensão escolhida."},{"title":"Compartilhar exige participar da grade","text":"No exemplo, cada cartão ocupa três linhas da grade externa e define grid-template-rows:subgrid quando suportado. Título, descrição e link passam a usar trilhas compartilhadas. A estrutura do HTML e o span precisam corresponder a esse contrato."},{"title":"Fallback deliberado","text":"A base usa cartões com grade interna independente e link ao final. Dentro de supports, a melhoria alinha as partes entre cartões. Consulte suporte no público pretendido e teste o layout base: uma verificação de sintaxe não garante que um desenho complexo esteja livre de bugs em todo navegador."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Subgrid com base independente</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\n.grade { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; max-inline-size: 48rem; }\n.cartao { display: grid; grid-template-rows: auto 1fr auto; gap: .75rem; padding: 1rem; border: 1px solid #71829a; }\n.cartao h2, .cartao p { margin: 0; }\n.cartao a { align-self: end; color: #174a7e; }\n@media (max-width: 30rem) { .grade { grid-template-columns: 1fr; } }\n@supports (grid-template-rows: subgrid) { .cartao { grid-row: span 3; grid-template-rows: subgrid; } }\n</style>\n</head>\n<body>\n<main><h1>Cartões alinhados</h1><div class=\"grade\"><article class=\"cartao\"><h2>OS-1</h2><p>Descrição curta.</p><a href=\"#os1\">Ver OS-1</a></article><article class=\"cartao\"><h2>OS-2 com título de várias palavras</h2><p>Descrição mais longa para observar o alinhamento das partes quando os cartões compartilham trilhas.</p><a href=\"#os2\">Ver OS-2</a></article></div><section id=\"os1\"><h2>Detalhes OS-1</h2></section><section id=\"os2\"><h2>Detalhes OS-2</h2></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"Os cartões usam duas colunas quando há espaço e uma coluna em área estreita. Com subgrid, títulos, descrições e links podem compartilhar as três trilhas de linha.","quiz":{"question":"O que subgrid acrescenta em relação a uma grade interna independente?","options":["Traduz o conteúdo dos cartões.","Elimina a necessidade de um grid pai.","Garante um tamanho fixo de texto para todas as telas.","Permite adotar as trilhas do grid pai na dimensão especificada."],"answer":3,"explanation":"O compartilhamento de trilhas ajuda a alinhar partes de itens relacionados."},"exercises":[{"title":"Versão de base","prompt":"Remova o bloco supports e compare o alinhamento com títulos e descrições diferentes.","hint":"Os cartões continuam tendo sua própria grade.","solution":"A base deve manter leitura e links disponíveis; o alinhamento entre partes pode ser diferente.","criteria":["Não perde conteúdo sem a melhoria.","Identifica o que subgrid acrescentava."],"id":1},{"title":"Contrato de três linhas","prompt":"Acrescente uma quarta parte ao cartão e revise grid-row:span3.","hint":"A quantidade de partes e trilhas precisa ser coerente.","solution":"Defina o novo contrato de linhas ou agrupe conteúdo; não presuma que uma parte extra cabe sem alterar a composição.","criteria":["Explica a incompatibilidade inicial.","Apresenta uma estrutura coerente revisada."],"id":2},{"title":"Compatibilidade","prompt":"Confira a documentação de suporte de grid-template-rows:subgrid e registre os navegadores-alvo do seu laboratório.","hint":"Separe suporte consultado de teste realmente realizado.","solution":"Documente a consulta e a execução disponível, mantendo fallback para os alvos não testados.","criteria":["Informa as versões testadas quando disponíveis.","Não afirma suporte universal sem evidência."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Grid_layout/Subgrid","caution":"","local":true,"hours":4,"minutes":45},{"id":33,"level":11,"title":"DevTools, overflow e custo de renderização","goal":"Investigar uma hipótese de CSS e registrar evidência reproduzível.","theory":[{"title":"Da aparência à regra","text":"Uma falha visual deve virar uma pergunta concreta: qual elemento excede o container, qual declaração vence ou qual contexto cria a sobreposição? Inspecione estilos calculados, box model e overlays de Grid/Flex para ligar a observação à regra responsável."},{"title":"Uma mudança por hipótese","text":"O exemplo contém uma tabela numa região deliberadamente rolável, não uma página inteira de largura fixa. Se houver rolagem horizontal inesperada na página, investigue o elemento que impõe o tamanho, incluindo mínimos intrínsecos, white-space, width e conteúdo sem quebra."},{"title":"Desempenho pede medição","text":"Transform e opacity frequentemente permitem caminhos de composição favoráveis, mas não há garantia universal de baixo custo. Efeitos, tamanho das camadas e o restante da página importam. Use ferramentas de performance e pintura numa carga reproduzível antes de atribuir lentidão a um seletor ou aplicar will-change em toda parte."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>DevTools, overflow e custo de renderização</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; padding: 1rem; color: #172b42; }\nmain { max-inline-size: 48rem; margin-inline: auto; }\n.tabela-regiao { overflow: auto; border: 2px solid #174a7e; }\ntable { border-collapse: collapse; inline-size: 100%; min-inline-size: 32rem; }\ncaption { text-align: start; font-weight: 700; padding: .75rem; }\nth, td { text-align: start; padding: .75rem; border-block-end: 1px solid #a9b8c8; }\n.tabela-regiao:focus-visible { outline: 3px solid #8a5200; outline-offset: 3px; }\n</style>\n</head>\n<body>\n<main><h1>Diagnóstico de largura</h1><div class=\"tabela-regiao\" tabindex=\"0\" role=\"region\" aria-label=\"Estoque por técnico\"><table><caption>Estoque fictício por técnico</caption><thead><tr><th scope=\"col\">Técnico</th><th scope=\"col\">Item</th><th scope=\"col\">Quantidade</th></tr></thead><tbody><tr><td>Técnico A</td><td>Rastreador modeloA</td><td>12</td></tr><tr><td>Técnico B</td><td>Rastreador modeloB</td><td>8</td></tr></tbody></table></div></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"Quando a tabela não cabe, sua região interna rola na horizontal; a largura fixa mínima da tabela não deve impor a mesma largura à página inteira.","quiz":{"question":"Qual é uma boa primeira pergunta para investigar overflow inesperado?","options":["Qual caixa e qual restrição de tamanho fazem o conteúdo exceder seu container?","Qual é o maior z-index que posso escrever?","Como ocultar toda a rolagem sem olhar o conteúdo?","Qual framework é obrigatório para qualquer tabela?"],"answer":0,"explanation":"Um diagnóstico liga o excesso de tamanho a um elemento e uma regra, preservando a informação necessária."},"exercises":[{"title":"Origem do tamanho","prompt":"Inspecione a tabela em uma janela estreita e identifique a declaração que impõe32rem.","hint":"Compare a tabela e a região externa.","solution":"Min-inline-size da tabela define a pressão; overflow:auto no wrapper mantém essa necessidade dentro da região.","criteria":["Identifica a declaração exata.","Distingue largura da página e da região."],"id":1},{"title":"Hipótese documentada","prompt":"Remova min-inline-size numa cópia e registre a consequência para leitura e quebra de células.","hint":"Uma largura menor não é automaticamente melhor para os dados.","solution":"Compare o conteúdo real e escolha entre reorganizar dados ou rolagem localizada conforme a tarefa.","criteria":["Mostra antes e depois.","Justifica a decisão pelo conteúdo da tabela."],"id":2},{"title":"Medição de efeito","prompt":"Descreva como compararia uma sombra simples e uma sombra complexa em muitos cartões.","hint":"Mantenha conteúdo, quantidade e ambiente equivalentes.","solution":"Use uma interação reproduzível e ferramentas de performance/pintura; registre condições e resultados sem culpar uma regra só por intuição.","criteria":["Define uma carga comparável.","Separa observação visual de evidência de custo."],"id":3}],"source":"https://web.dev/learn/css/performance","caution":"","local":true,"hours":4,"minutes":45},{"id":34,"level":12,"title":"CSS para impressão e saída compartilhável","goal":"Adaptar uma página à mídia impressa sem depender do fundo colorido.","theory":[{"title":"Outra mídia, outra tarefa","text":"Media print permite adaptar apresentação ao processo de impressão ou geração de PDF do navegador. Um menu de navegação pode ser dispensável no papel, enquanto número da OS, status e conteúdo principal precisam continuar visíveis."},{"title":"Quebras são preferências, não promessas","text":"Break-inside:avoid pode ajudar a manter um cartão junto, mas o navegador ainda precisa lidar com a área da página e conteúdo maior que uma folha. Não trate uma regra isolada como garantia de paginação perfeita. Confira a prévia e um PDF real quando esse formato for uma entrega."},{"title":"Contexto e cores","text":"Muitas configurações não imprimem fundos. Use texto e bordas que preservem a informação sem depender do preenchimento. URLs e referências podem precisar de uma representação escrita no papel; evite adicionar links internos ou dados sensíveis indiscriminadamente como conteúdo gerado."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>CSS para impressão e saída compartilhável</title>\n<style>\nbody { font-family: system-ui; padding: 1rem; color: #172b42; background: #edf2f8; }\nmain { max-inline-size: 42rem; margin-inline: auto; }\nnav { padding: 1rem; background: #eaf3fb; }\na { color: #174a7e; }\n.ordem { padding: 1rem; margin-block: 1rem; border: 2px solid #71829a; background: #fff; }\n@media print { body { color: #000; background: #fff; padding: 0; } nav { display: none; } .ordem { color: #000; background: #fff; border-color: #000; break-inside: avoid; } main { max-inline-size: none; } }\n</style>\n</head>\n<body>\n<main><h1>Resumo de ordens</h1><nav aria-label=\"Navegação do resumo\"><a href=\"#os1\">OS-1</a> · <a href=\"#os2\">OS-2</a></nav><article class=\"ordem\" id=\"os1\"><h2>OS-1</h2><p>Status: pendente de conferência.</p><p>Serviço: instalação de equipamento fictício.</p></article><article class=\"ordem\" id=\"os2\"><h2>OS-2</h2><p>Status: concluída.</p><p>Serviço: revisão de equipamento fictício.</p></article></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"Na tela há fundo e navegação. Na prévia de impressão o menu é ocultado e as ordens continuam com texto preto e bordas visíveis.","quiz":{"question":"Por que não depender apenas de uma cor de fundo para o status impresso?","options":["Porque CSS nunca atua na impressão.","A configuração de impressão pode omitir fundos, então o status precisa de texto legível.","Porque todo navegador imprime todas as cores de forma idêntica.","Porque print transforma automaticamente qualquer texto em tabela."],"answer":1,"explanation":"A saída pode ter restrições distintas da tela; informação textual e contraste preservam o significado."},"exercises":[{"title":"Prévia","prompt":"Abra a prévia de impressão e compare menu, cores e bordas com a tela.","hint":"A media query print precisa ser observada nessa mídia.","solution":"Registre as diferenças reais e confirme que OS e status continuam identificáveis.","criteria":["O menu não é necessário para ler as ordens.","O status permanece explícito."],"id":1},{"title":"Conteúdo grande","prompt":"Acrescente várias observações a uma ordem e veja como o navegador trata uma caixa maior que uma página.","hint":"Avoid não torna a caixa menor que o papel.","solution":"Revise quebras e estrutura; documente o comportamento observado na prévia.","criteria":["Não promete paginação perfeita por uma única regra.","Mantém toda a descrição na saída."],"id":2},{"title":"Sem fundo","prompt":"Desative gráficos de fundo na impressão e confira as ordens.","hint":"Texto e borda precisam funcionar sozinhos.","solution":"O material permanece compreensível porque não usa cor como único status.","criteria":["Confere os dois status.","Registra a configuração usada."],"id":3}],"source":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Media_queries/Printing","caution":"","local":true,"hours":4,"minutes":45},{"id":35,"level":12,"title":"Resiliência a textos, zoom e estados variados","goal":"Montar uma matriz pequena de revisão com conteúdo realista.","theory":[{"title":"Uma amostra feliz não basta","text":"Um layout pode funcionar com três palavras e falhar com nome longo, quantidade grande ou texto ampliado. Prepare casos de conteúdo representativos e de limite. O objetivo não é adivinhar todo dado futuro, mas tornar os contratos de tamanho e quebra observáveis."},{"title":"Revisão por tarefa","text":"Pergunte se a pessoa consegue identificar a ordem, ler o status e alcançar o link na condição testada. Um screenshot sem overflow não prova que a navegação de teclado funciona. Combine verificação visual com interação e, quando disponível, tecnologia assistiva."},{"title":"Evidência repetível","text":"Registre navegador, largura aproximada em CSS, zoom, conteúdo e resultado. Diferencie o que foi executado de uma consulta à documentação. A conclusão de uma revisão deve indicar problemas e limites conhecidos, sem transformar uma lista de checks em uma certificação automática de acessibilidade."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Resiliência a textos, zoom e estados variados</title>\n<style>\n* { box-sizing: border-box; }\nbody { font-family: system-ui; margin: 0; padding: 1rem; color: #172b42; line-height: 1.6; }\nmain { max-inline-size: 48rem; margin-inline: auto; }\n.cartao { display: grid; gap: .8rem; padding: 1rem; border: 2px solid #71829a; overflow-wrap: anywhere; }\n.cartao h2, .cartao p { margin: 0; }\n.cartao a { justify-self: start; color: #174a7e; padding-block: .4rem; }\na:focus-visible { outline: 3px solid #8a5200; outline-offset: 3px; }\n@media (min-width: 38rem) { .cartao { grid-template-columns: minmax(0, 1fr) auto; } .descricao { grid-column: 1 / -1; } }\n</style>\n</head>\n<body>\n<main><h1>Teste de conteúdo</h1><article class=\"cartao\"><h2>OS-123456789012345678901234567890</h2><p>Status: confirmação operacional pendente</p><p class=\"descricao\">Cliente com nome fictício muito extenso e instruções que precisam continuar disponíveis, mesmo quando o texto ocupa várias linhas numa janela estreita.</p><a href=\"#detalhes\">Ler todos os detalhes da ordem</a></article><section id=\"detalhes\"><h2>Detalhes completos</h2><p>O link possui um destino real neste exemplo.</p></section></main>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"Identificador, status e descrição quebram quando necessário; o cartão cresce e o link continua legível e alcançável.","quiz":{"question":"O que uma matriz de revisão deve registrar para tornar uma falha reproduzível?","options":["Apenas que a tela parece bonita.","Somente o nome comercial do aparelho.","Condições como largura, zoom, navegador, conteúdo e passos de interação.","A certeza de que toda condição não testada também funciona."],"answer":2,"explanation":"Uma evidência útil informa as condições e os passos para repetir a observação."},"exercises":[{"title":"Matriz mínima","prompt":"Teste duas larguras,200% de zoom e navegação por teclado. Registre resultado e algum limite observado.","hint":"Faça condições distintas sem esconder texto para passar.","solution":"Monte uma tabela com condição, passos, resultado e ajuste; não afirme ter testado recursos indisponíveis.","criteria":["Registra todas as condições executadas.","Diferencia resultado e hipótese."],"id":1},{"title":"Conteúdo extremo","prompt":"Substitua a descrição por uma palavra sem espaços e depois por vários parágrafos.","hint":"São pressões diferentes de conteúdo.","solution":"Revise a política de quebra e altura automática; preserve leitura em ambos os casos.","criteria":["Compara os dois formatos.","Não usa corte como solução padrão."],"id":2},{"title":"Foco e destino","prompt":"Acione o link por teclado e confira se o destino pode ser localizado visualmente.","hint":"O link deve ter nome e alvo claros.","solution":"Mantenha heading no destino e estilo de foco no link; documente a experiência observada.","criteria":["Chega ao conteúdo correspondente.","Não depende só do screenshot do cartão."],"id":3}],"source":"https://www.w3.org/TR/WCAG22/","caution":"","local":true,"hours":4,"minutes":45},{"id":36,"level":12,"title":"Projeto final: painel de OS e estoque","goal":"Integrar componentes, adaptação, foco e documentação num painel local.","theory":[{"title":"Uma integração de apresentação","text":"O exemplo reúne navegação para seções, indicadores, cartões de ordens e um bloco de detalhes nativo. Ele demonstra CSS e HTML local: não consulta banco, não confirma serviços e não grava estoque. Os números são fictícios e devem ser identificados como dados de estudo."},{"title":"Base funcional e melhorias","text":"A base tem uma coluna, links e detalhes utilizáveis sem depender de container queries. Uma media query acrescenta regiões lado a lado, e a query reorganiza um cartão conforme seu host. Os tokens definem decisões visuais e as camadas dão uma ordem de manutenção."},{"title":"Entregar e explicar","text":"Para concluir, personalize conteúdo e componentes, execute uma matriz de teclado, largura, zoom, texto longo e impressão, e escreva um README. Registre limitações de compatibilidade e o que exigiria JavaScript ou backend numa aplicação real. O resultado da revisão deve mostrar raciocínio e evidência, além do desenho final."}],"code":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Projeto final: painel de OS e estoque</title>\n<style>\n@layer base, layout, components, states;\n@layer base { :root { --fundo: #edf2f8; --superficie: #fff; --texto: #172b42; --borda: #71829a; --acao: #174a7e; --espaco: 1rem; } * { box-sizing: border-box; } body { margin: 0; font-family: system-ui, sans-serif; line-height: 1.6; color: var(--texto); background: var(--fundo); } h1, h2, h3, p { margin-block-start: 0; } a { color: var(--acao); } }\n@layer layout { .pagina { max-inline-size: 72rem; margin-inline: auto; padding: var(--espaco); } .barra { display: flex; flex-wrap: wrap; gap: .75rem 1.25rem; padding-block: .75rem; } .painel, .indicadores { display: grid; gap: var(--espaco); } .indicadores { grid-template-columns: repeat(auto-fit, minmax(min(100%, 11rem), 1fr)); } .coluna { min-inline-size: 0; } @media (min-width: 48rem) { .painel { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); } } }\n@layer components { .superficie, .ordem { padding: var(--espaco); border: 1px solid var(--borda); border-radius: .6rem; background: var(--superficie); overflow-wrap: anywhere; } .indicador strong { display: block; font-size: 1.7rem; } .host { margin-block-end: var(--espaco); } .ordem { display: grid; gap: .75rem; } .ordem h3, .ordem p { margin: 0; } .estado { align-self: start; justify-self: start; padding: .25rem .55rem; border: 1px solid currentColor; color: #704000; background: #fff2d4; } .acao { display: inline-block; padding: .6rem .8rem; color: #fff; background: var(--acao); border-radius: .3rem; text-decoration: none; } summary { cursor: pointer; font-weight: 700; padding-block: .4rem; } details p { margin-block-start: .75rem; } .estoque { padding-inline-start: 1.2rem; } @supports (container-type: inline-size) { .host { container: ordem / inline-size; } @container ordem (min-width: 28rem) { .ordem { grid-template-columns: minmax(0, 1fr) auto; } .ordem .acao { justify-self: start; } } } }\n@layer states { :is(a, summary):focus-visible { outline: 3px solid #8a5200; outline-offset: 3px; } .acao:hover { background: #103a65; } }\n@media print { body { background: #fff; color: #000; } .barra { display: none; } .painel { display: block; } .superficie, .ordem { border-color: #000; break-inside: avoid; margin-block-end: 1rem; } .acao { color: #000; background: #fff; border: 1px solid; } }\n</style>\n</head>\n<body>\n<div class=\"pagina\"><header><p>Laboratório CSS · dados fictícios</p><h1>Painel da oficina</h1><nav class=\"barra\" aria-label=\"Seções do painel\"><a href=\"#indicadores\">Indicadores</a><a href=\"#ordens\">Ordens</a><a href=\"#estoque\">Estoque</a></nav></header><main><section id=\"indicadores\" aria-labelledby=\"titulo-indicadores\"><h2 id=\"titulo-indicadores\">Indicadores</h2><div class=\"indicadores\"><p class=\"superficie indicador\">Ordens abertas<strong>8</strong></p><p class=\"superficie indicador\">Aguardando conferência<strong>3</strong></p><p class=\"superficie indicador\">Unidades em estoque<strong>25</strong></p></div></section><div class=\"painel\"><section class=\"coluna\" id=\"ordens\" aria-labelledby=\"titulo-ordens\"><h2 id=\"titulo-ordens\">Ordens de serviço</h2><div class=\"host\"><article class=\"ordem\"><div><h3>OS-1</h3><p>Instalação de equipamento</p></div><span class=\"estado\">Pendente</span><a class=\"acao\" href=\"#detalhes-os1\">Ver detalhes da OS-1</a></article></div><div class=\"host\"><article class=\"ordem\"><div><h3>OS-2</h3><p>Revisão e conferência de evidências</p></div><span class=\"estado\">Em revisão</span></article></div><details class=\"superficie\" id=\"detalhes-os1\"><summary>Detalhes da OS-1</summary><p>Equipamento fictícioA, técnico de exemplo e conferência operacional pendente.</p><p>Esta interface não executa confirmação nem altera saldo.</p></details></section><aside class=\"coluna superficie\" id=\"estoque\" aria-labelledby=\"titulo-estoque\"><h2 id=\"titulo-estoque\">Resumo de estoque</h2><ul class=\"estoque\"><li>ItemA:12 unidades</li><li>ItemB:8 unidades</li><li>ItemC:5 unidades</li></ul><p>Dados locais estáticos para revisar a apresentação.</p></aside></div></main><footer><p>Projeto de estudo: personalize, teste e documente suas decisões.</p></footer></div>\n</body>\n</html>\n","filename":"index.html","language":"html","run":"Salve o exemplo inteiro como index.html e abra no navegador. Recarregue após salvar. Teste os estados indicados e inspecione as regras aplicáveis.","expected":"Em espaço pequeno as regiões se empilham; em área ampla ordens e estoque ficam lado a lado. Links navegam para seções, o summary abre detalhes com teclado e os dados continuam claramente fictícios.","quiz":{"question":"Qual evidência completa melhor a entrega do painel CSS?","options":["Somente uma imagem da tela larga sem interação.","Uma afirmação de que CSS já gravou os dados no banco.","Remover todos os textos longos para evitar testar quebras.","Matriz de testes executados e README com decisões, compatibilidade e limites de funcionalidade."],"answer":3,"explanation":"Uma entrega revisável comunica o que funciona, em quais condições foi testado e quais capacidades não foram implementadas."},"exercises":[{"title":"Personalização coerente","prompt":"Adicione uma terceira ordem e um novo indicador reutilizando os componentes, com texto propositalmente longo.","hint":"Não crie uma regra por ID da ordem para repetir o estilo.","solution":"Use as classes existentes e revise a matriz de conteúdo; crie variante apenas se houver uma diferença de contrato real.","criteria":["O novo conteúdo usa componentes comuns.","A versão estreita conserva toda a informação."],"id":1},{"title":"Revisão integrada","prompt":"Teste320px e uma área ampla,200% de zoom, Tab/Shift+Tab, abertura de details e prévia de impressão.","hint":"Registre passos e resultados, incluindo limitações do ambiente disponível.","solution":"Monte a matriz e corrija falhas observadas, preservando foco e conteúdo nas duas composições.","criteria":["Os destinos e details são utilizáveis por teclado.","A evidência distingue teste realizado e suporte apenas consultado."],"id":2},{"title":"Documentação da entrega","prompt":"Escreva README com execução, ordem das camadas, componentes, pontos de adaptação e limites do painel.","hint":"Explique que os dados são estáticos.","solution":"Documente arquivo único, tokens, media/container queries, fallback, matriz de revisão e o que exigiria lógica/backend.","criteria":["Outra pessoa consegue abrir e revisar o exemplo.","Não promete consulta, persistência ou confirmação que o código não implementa."],"id":3}],"source":"https://web.dev/learn/design/","caution":"","local":true,"hours":4,"minutes":45}]};
